'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["mt"]={"g-flurpruefung":["X'inhu inkluż fi spezzjoni viżwali u funzjonali qabel ma jibda x-xogħol?","Qabel l-ewwel missjoni tal-ġurnata.","Iċċekkja l-livell tal-fjuwil u l-kulur tal-vettura biss.","Iċċekkja l-brejkijiet, l-istering, il-frieket, it-tajers u l-apparat tas-sigurtà skont l-istruzzjonijiet tat-tħaddim.","Wettaq test drive bit-tagħbija mgħollija.","L-ispezzjoni ta 'kuljum tinkludi l-partijiet u l-funzjonijiet rilevanti għas-sigurtà skont l-istruzzjonijiet tat-tħaddim."],"g-rueckhalt":["Kif tittratta s-sistema eżistenti tat-trażżin tas-sewwieq?","It-trakk tal-forklift għandu sistema obbligatorja ta 'trażżin.","Użaha kif suppost waqt is-sewqan.","Uża biss fuq art irregolari.","Iddiżattivaha għal vjaġġi qosra.","Is-sistemi ta' trażżin maħsuba għandhom jintużaw skond l-istruzzjonijiet tal-manifattur; jipprovdu protezzjoni partikolari fil-każ ta' avvenimenti ta' twaddib."],"g-mangelmelden":["X'japplika għal forklift b'furketta bil-ħsara?","Meta tkun qed tiċċekkja, tinnota tinda mgħawweġ b'mod ċar.","Jekk possibbli, qassam it-tagħbija lill-tine l-oħra.","Issuq biss tagħbijiet ħfief sas-servizz li jmiss.","Tużax il-forklift u rrapporta d-difett lill-persuna responsabbli.","Tagħmir għall-immaniġġjar tat-tagħbija bil-ħsara jista 'jfalli; Id-difetti relatati mas-sigurtà jeħtieġu għeluq sakemm jiġu kjarifikati."],"g-einweisung":["Inti taqleb għal forklift b'kontrolli differenti. X'inhu meħtieġ qabel l-użu?","L-operazzjoni hija differenti mill-vettura preċedenti tiegħek.","Istruzzjoni relatata mal-apparat u konformità mal-istruzzjonijiet tat-tħaddim.","Spjegazzjoni qasira minn kollega mhux involut hija dejjem biżżejjed.","Ebda informazzjoni addizzjonali jekk għandek liċenzja tal-forklift.","Kwalifika ġenerali ma tissostitwixxix l-istruzzjoni meħtieġa fuq l-apparat li fil-fatt jintuża."],"g-anbaugeraet":["Għandek tuża attachment. X'tiċċekkja l-ewwel?","Biċċa ġdida ta 'tagħmir tibdel il-mod kif it-tagħbija tinġabar.","Jekk it-twaħħil jaqbilx mal-approvazzjoni tal-vettura u t-tagħbija permissibbli.","Biss jekk l-apparat jistax jitwaħħal viżwalment.","Jekk it-twaħħil jistax jiġi installat mingħajr dokumentazzjoni.","L-annessi jistgħu jibdlu l-kapaċità tat-tagħbija li jifdal u ċ-ċentru tat-tagħbija; L-approvazzjonijiet u l-informazzjoni dwar il-kapaċità tat-tagħbija għandhom jiġu kkontrollati."],"g-diagramm":["Għaliex għandek bżonn id-dijagramma tal-kapaċità tat-tagħbija?","Tagħbija tqila hija preżenti biċ-ċentru tal-gravità 'l barra.","Biex tiddetermina l-iqsar rotta.","Biex tivvaluta t-tagħbija massima permissibbli skont l-għoli tal-irfigħ u ċ-ċentru tat-tagħbija.","Biex tiddetermina l-kapaċità tat-tank.","Tagħbijiet permissibbli jiddependu, fost affarijiet oħra, fuq id-distanza taċ-ċentru tat-tagħbija u l-għoli tal-irfigħ."],"g-lastschwerpunkt":["X'jiġri tipikament meta ċ-ċentru tal-gravità jimxi aktar 'il quddiem?","Tagħbija twila tisporġ 'il barra minn quddiem il-frieket.","Il-kapaċità tat-tagħbija permissibbli tista' tonqos.","Il-kapaċità tal-ġarr dejjem qed tiżdied.","Id-distanza m'għandha l-ebda influwenza fuq il-mument tat-twaddib.","Distanza akbar miċ-ċentru tat-tagħbija żżid il-mument tat-twaddib u tista 'tnaqqas il-kapaċità tat-tagħbija permissibbli."],"g-gabelabstand":["Kif għandhom il-frieket jiġbru pallet adattat?","Trid tieħu pallet mgħobbi b'mod uniformi.","Bit-tines qrib kemm jista' jkun u fuq kantuniera waħda biss.","B'distanza daqshekk kbira li l-pallet jinqaleb fuq il-ġenb.","Bi spazjar xieraq tad-denti u undercarriage suffiċjenti u żona ta 'appoġġ.","It-tagħbija għandha tkun sostnuta b'mod sikur u kemm jista 'jkun indaqs madwar il-frieket."],"g-schieflast":["Tagħbija hija f'munzelli b'mod instabbli. X'inhu sewwa?","Kaxxi tal-kartun jistgħu jaqgħu meta jitneħħew.","Ibda bil-mod; il-ħlas jistabbilizza ruħu.","Qabel ma taqbad it-tagħbija, waħħalha biżżejjed jew erġa' armata.","Għolli t-tagħbija 'l fuq mill-għoli tar-ras sabiex ma tfixkilx.","Merkanzija maħlula jew instabbli tista 'taqa' u tipperikola n-nies; wettaq miżuri ta 'sigurtà l-ewwel."],"g-personen":["Tista' persuna tittella' fuq frieket ordinarji?","Kollega jrid jilħaq dawl.","Iva, jekk il-kollega jilbes elmu.","Le, faċilitajiet nominati u permessi biss jistgħu jintużaw minn nies skont rekwiżiti speċjali.","Iva, jekk biss għoli żgħir jiġi avviċinat.","Frieket normali mhumiex pjattaforma tax-xogħol personali; It-trasport u l-irfigħ tan-nies huwa soġġett għal rekwiżiti speċjali."],"g-transporthoehe":["Kif normalment tittrasporta pallet?","It-triq hija ċara u livellata.","Bit-tagħbija mgħollija biss sa fejn meħtieġ u skond l-istruzzjonijiet tat-tħaddim.","Bit-tagħbija mgħollija kemm jista 'jkun biex tidher aħjar.","Bl-arblu tal-irfigħ inklinat bil-qawwa 'l quddiem, irrispettivament mit-tagħbija.","Pożizzjoni baxxa tat-trasport tnaqqas ir-riskju ta 'qlib u ħabtiet; L-istruzzjonijiet tal-apparat huma deċiżivi."],"g-kurvenfahrt":["Għaliex ir-rokna malajr bi trakk tal-forklift huwa perikoluż?","Trid toħroġ malajr minn triq dejqa.","Minħabba li tbattal il-batterija aktar malajr.","Minħabba li l-forklift awtomatikament tidderieġi aħjar.","Minħabba li l-forzi laterali jaffettwaw l-istabbiltà u jistgħu jwasslu biex jinqalbu.","Waqt ir-rokna, jidħlu forzi addizzjonali; il-veloċità għandha tiġi aġġustata għat-tagħbija u l-kundizzjonijiet."],"g-ladebruecke":["X'tiċċekkja qabel issuq fuq pont tat-tagħbija?","Għandek issuq fi trakk.","Biss jekk it-triq tidher wiesgħa biżżejjed.","Kapaċità tat-tagħbija, appoġġ sikur u protezzjoni kontra ċ-ċaqliq kif ukoll l-iżgurar tal-vettura.","Eżatt jekk id-dawl hux mixgħul.","Il-pontijiet tat-tagħbija u l-vetturi għandhom ikunu mwaħħla kontra l-moviment u adattati għat-tagħbija."],"g-fussgaenger":["Kif taġixxi f'intersezzjoni ta' konfużjoni ma' nies mexjin?","Konnessjonijiet viżwali huma ristretti.","Issuq b'veloċità xierqa, waqqaf jekk meħtieġ u tiżgura viżibilità sigura.","Dejjem titlob id-dritt tal-passaġġ meta ġġorr tagħbija.","Ħonk biss u kompli ssuq.","Il-persuni mexjin għandhom bżonnijiet speċjali ta' protezzjoni; Il-veloċità, il-viżibilità u l-komunikazzjoni għandhom jiġu adattati għar-rotta tat-traffiku."],"g-batterieladen":["X'għandek tagħti attenzjoni partikolari meta tiċċarġja batterija tas-sewqan?","Jintuża stazzjon tal-iċċarġjar tal-batterija.","Il-post tal-iċċarġjar jista' jintgħażel irrispettivament mill-istruzzjonijiet tal-manifattur.","Fjammi miftuħa huma permessi sakemm it-trakk ikun wieqaf.","Żona ta 'tagħbija xierqa, ventilazzjoni suffiċjenti u speċifikazzjonijiet tal-manifattur kif ukoll protezzjoni min-nar u splużjoni.","Meta tiċċarġja, jistgħu jinqalgħu perikli minn enerġija elettrika, gassijiet u kimiċi; il-miżuri protettivi pprovduti għandhom jiġu osservati."],"h-beauftragt":["Taħt liema kundizzjonijiet titħalla topera pjattaforma tax-xogħol mill-ajru b'mod indipendenti?","Għandek tuża pjattaforma tax-xogħol fil-kumpanija.","Jekk għandek liċenzja tas-sewqan tal-karozza.","Jekk inti addattat, mgħallem jew kwalifikat u kkummissjonat minn min iħaddem.","Jekk qatt rajt pjattaforma tax-xogħol.","Min iħaddem għandu jiżgura l-adegwatezza, il-kwalifiki u l-inkarigi skont ir-rekwiżiti operattivi."],"h-vorpruefung":["X'għandu jiġi ċċekkjat qabel ma jibda x-xogħol mal-pjattaforma tax-xogħol mill-ajru?","Il-palk kien barra matul il-lejl.","Test viżwali u funzjonali skont l-istruzzjonijiet tal-manifattur inkluż tagħmir ta' sikurezza.","Biss il-kulur u l-età tal-palk.","Jekk il-materjal tax-xogħol huwiex diġà fuq il-pjattaforma.","Qabel l-użu, il-magna, il-kontrolli, il-funzjonijiet ta 'emerġenza u l-ħsara viżibbli għandhom jiġu kkontrollati skont l-istruzzjonijiet tat-tħaddim."],"h-tragfaehigkeit":["Liema informazzjoni tiddetermina t-tagħbija permissibbli fuq il-basket tax-xogħol?","Żewġ persuni jixtiequ jieħdu għodda addizzjonali magħhom.","In-nies huma liberi li jistmaw il-piż totali permissibbli.","Jgħodd biss il-piż tal-itqal persuna.","L-ispeċifikazzjoni tal-kapaċità tat-tagħbija għal nies, għodda u materjal m'għandhiex tinqabeż.","It-tagħbija nominali tirreferi għat-tagħbija totali permissibbli, inkluż kwalunkwe materjal li jinġarr."],"h-untergrund":["X'taħseb qabel ma twaqqaf palk bl-appoġġi?","Qed taħdem ħdejn żona mimlija.","Biss fil-firxa tal-boom.","Iċċekkja l-kapaċità li ġġorr it-tagħbija u l-uniformità tas-superfiċje kif ukoll l-appoġġ xieraq skont l-istruzzjonijiet.","Fuq l-inqas numru possibbli ta 'appoġġi estiżi.","Art insuffiċjenti jew appoġġ mhux xieraq jista 'jwassal għal telf ta' stabbiltà."],"h-wind":["Riħ qawwi jidħol pulzieri Kif tmur dwarha?","Issib ruħek ma 'palk ta' barra.","Osserva l-limiti tal-manifattur u jekk jinqabżu, waqqaf it-tħaddim jew baxxi l-basket b'mod sigur.","Estendi l-pjattaforma kemm jista 'jkun sabiex tkun aktar stabbli.","Irreaġixxi biss jekk jaqgħu oġġetti maħlula.","Il-kundizzjonijiet tar-riħ permessi mill-manifattur huma limiti operattivi; Ir-riħ jista 'joħloq forzi addizzjonali perikolużi."],"h-strom":["Int trid taħdem ħdejn linja tal-elettriku fl-għoli. X'inhu kruċjali?","Linja ħaj tinsab fiż-żona tax-xogħol.","Elmu jieħu post iż-żamma ta' distanza sigura.","Sempliċement iżola l-basket u taħdem mingħajr koordinazzjoni.","Iċċara ż-żona ta' periklu u tiżgura d-distanzi protettivi meħtieġa jew miżuri xierqa oħra.","Flashover elettriku huwa wkoll possibbli mingħajr kuntatt dirett; Il-miżuri protettivi meħtieġa għandhom jiġu determinati qabel il-bidu tal-operazzjoni."],"h-notablass":["Għaliex jeħtieġ li tkun magħrufa l-proċedura ta' tnaqqis ta' emerġenza?","Falliment tal-kontroll normali huwa possibbli.","Sabiex f'każ ta 'malfunzjoni, salvataġġ sikur huwa possibbli skond l-apparat.","Sabiex l-apparat jaħdem aktar malajr fl-operat normali.","Biex tissostitwixxi l-ittestjar regolari.","Kontrolli ta 'emerġenza, kunċetti ta' tnaqqis ta 'emerġenza u salvataġġ għandhom ikunu magħrufa u funzjonali qabel l-użu."],"h-gelaender":["Kif tikseb għoli addizzjonali fil-basket tax-xogħol?","Il-punt tal-muntaġġ huwa ftit lil hinn mill-firxa tiegħek.","Tlugħ fuq l-ilqugħ tal-basket.","Poġġi bord fuq il-puġġaman.","Uża pjattaforma xierqa b'għoli biżżejjed tax-xogħol; titlax fuq il-poġġamani.","It-tixbit taċ-ċint jew l-elevazzjonijiet improvizzati jipperikola l-protezzjoni tal-waqgħa."],"h-psaga":["Liema rekwiżiti japplikaw għat-tagħmir personali għall-protezzjoni kontra l-waqgħa?","Tuża pjattaforma tax-xogħol li għaliha hija pprovduta sistema ta' trażżin.","Kwalunkwe punt ta 'ankra barra l-basket huwa dejjem biżżejjed.","Osserva l-valutazzjoni tar-riskju, l-informazzjoni tal-manifattur u l-punti tal-ankrar xierqa.","Tużax xi sigurtà jekk il-basket ikollu puġġaman.","Jekk u liema PPE huwiex meħtieġ huwa ddeterminat mill-valutazzjoni tar-riskju, il-kostruzzjoni tal-istadju u l-istruzzjonijiet tat-tħaddim."],"h-verfahren":["Jista 'l-palk jiġi mċaqlaq bil-pjattaforma mgħollija?","Il-post tax-xogħol jinsab ftit metri bogħod.","Biss jekk il-mudell u l-kundizzjonijiet operattivi jippermettu dan skont l-istruzzjonijiet tal-manifattur.","Dejjem, sakemm kulħadd iżomm.","Le, qatt irrispettivament mid-disinn u l-approvazzjoni tal-manifattur.","Il-moviment fil-pożizzjoni mgħollija jiddependi fuq l-apparat u huwa permess biss fil-kundizzjonijiet ta' tħaddim approvati."],"h-kollision":["X'għandu jiġi organizzat meta taħdem ħdejn krejnijiet jew magni oħra?","Partijiet li jiċċaqilqu jistgħu jilħqu l-basket tax-xogħol.","Xejn; il-basket tax-xogħol huwa dejjem viżibbli.","Dejjem issuq il-basket tax-xogħol fuq il-magni l-oħra.","Ikkoordina żoni tax-xogħol biex tevita ħabtiet jew punti ta 'qross.","It-tħaddim simultanju tal-magni jeħtieġ proċessi ta 'xogħol koordinati u protezzjoni kontra ħabtiet jew iġġammjar."],"h-einstieg":["Kif tidħol jew tħalli l-basket tax-xogħol?","Inti tilħaq il-basket fil-livell tal-art.","Tlugħ fuq il-puġġaman ta 'barra.","Permezz tal-aċċess maħsub f'pożizzjoni sigura skont l-istruzzjonijiet tat-tħaddim.","Permezz ta’ sellum imqiegħed ħdejha bil-boom estiż.","L-aċċess maħsub u l-istruzzjonijiet tal-manifattur għandhom jiġu rispettati; Tixbit mhux ikkontrollat ​​minn fuq joħloq riskju li jaqa’."],"h-defekt":["Il-faċilità ta’ waqfien ta’ emerġenza ma taħdimx. X'qed tagħmel?","Inti ser tiskopri d-difett waqt l-ispezzjoni.","Tużax il-pjattaforma u rrapporta d-difett.","Kompli aħdem jekk il-kontrolli normali jkunu qed jaħdmu.","Tejp is-swiċċ sabiex ħadd ma jħaddem.","Il-falliment ta 'apparat ta' sikurezza huwa difett rilevanti għas-sikurezza u jipprevjeni tħaddim sikur."],"h-sicht":["Il-moviment tas-sewqan ma jistax jidher minħabba ostaklu. Kif tmur dwar dan?","Għandek timxi stadju mobbli.","Issuq bil-mod mingħajr viżibilità.","Jiddependi biss fuq l-indikatur tad-distanza.","Waqqaf il-moviment u jiżgura viżibilità jew istruzzjoni sigura skont l-istruzzjonijiet tat-tħaddim.","Qabel il-proċedura, in-nies, l-ostakli u r-rotot tat-traffiku għandhom jiġu mistħarrġa b'mod sigur."],"h-rettung":["X'jinvolvi l-ippjanar tal-iskjerament meta taħdem f'għoli akbar?","L-istadju jintuża f'żona remota.","It-tul tax-xogħol ippjanat biss.","Kunċett ta' salvataġġ adattat b'nies aċċessibbli u mħarrġa u proċeduri ta' tnaqqis ta' emerġenza.","Is-suppożizzjoni li d-dipartiment tan-nar se jsolvi kwalunkwe problema immedjatament.","Salvataġġ effettiv għandu jiġi organizzat minn qabel, anke jekk il-kontrolli normali jfallu."],"k-befaehigung":["X'inhu meħtieġ biex tħaddem krejn b'mod indipendenti?","Impjegat ġdid suppost jieħu f'idejh ix-xogħol tal-krejn.","Adattabbiltà u kwalifiki meħtieġa, istruzzjoni u assenjazzjoni korrispondenti.","Liċenzja tas-sewqan tal-karozza hija biżżejjed.","Jaraw darba huwa biżżejjed.","Ix-xogħol tal-krejn jista' jiġi assenjat biss lil persuni kwalifikati u awtorizzati; L-istruzzjoni tat-tagħmir hija parti minnha."],"k-funktionspruefung":["X'hemm bżonn biex tiċċekkja l-krejn qabel il-bidu tax-xift?","Inti tieħu f'idejha krejn fuq ġewwa.","Aqra biss il-ħin tat-tħaddim fuq il-pjanċa tal-isem.","Iċċekkja l-funzjonijiet rilevanti għas-sigurtà u d-difetti viżibbli skont l-istruzzjonijiet tat-tħaddim.","Ittestja l-krejn b'tagħbija massima mingħajr verifika.","Il-kontroll operattiv obbligatorju jservi biex jidentifika difetti perikolużi fi stadju bikri."],"k-traglast":["X'inhu s-sinifikat tal-kapaċità tat-tagħbija permissibbli?","Tagħbija għandha titneħħa.","Hija rakkomandazzjoni li ma torbotx.","Japplika biss meta l-ganċ ikun kompletament miġbud.","Il-kapaċità tat-tagħbija permissibbli għall-kundizzjoni operattiva rispettiva m'għandhiex tinqabeż.","Tagħbijiet permissibbli għal ċerti tipi ta 'krejnijiet jistgħu jiddependu fuq ir-raġġ, il-pożizzjoni tal-boom u l-armament."],"k-personen":["X'japplika għal nies taħt tagħbijiet sospiżi?","It-tagħbija titmexxa fuq żona tax-xogħol.","Iż-żona ta' periklu għandha tinżamm ċara; ħadd ma jitħalla jidħol taħt it-tagħbija sospiża.","Elmu jippermettilek li toqgħod direttament taħtu.","Qsimijiet qosra huma permessi jekk il-krejn ikun miexi bil-mod.","Tagħbijiet sospiżi joħolqu riskju li jaqgħu u tgħaffiġ; In-nies għandhom jinżammu 'l barra miż-żona ta' periklu."],"k-signale":["Ma tistax tara l-attakkant u ikollok sinjali kontradittorji. X'qed tagħmel?","Il-komunikazzjoni mhix ċara.","Kompli l-aħħar kmand tas-sewqan.","Waqqaf il-moviment u ċċara b'mod ċar il-komunikazzjoni.","Waħħal it-tagħbija aktar malajr, mingħajr konsultazzjoni.","Movimenti sikuri tat-tagħbija jeħtieġu sinjali ċari u komunikazzjoni ċara."],"k-sicht":["Min se jipprovdi appoġġ waqt it-trasport jekk l-operatur tal-krejn ma jistax jara kompletament il-mogħdija tat-tagħbija?","Pilastru tas-sala joskura t-triq.","Persuna li tinzerta tgħaddi mingħajr qbil minn qabel.","Ħadd; il-ganċ biss huwa importanti.","Persuna addattata u mgħallma b'fehim miftiehem b'mod ċar.","Jekk il-mogħdija tat-tagħbija ma tkunx viżibbli, hija meħtieġa struzzjoni xierqa jew soluzzjoni sigura oħra."],"k-ruck":["Għaliex għandhom jiġu evitati movimenti tal-krejn jerky?","Tagħbija tqila tibda titbandal.","Huma joħolqu stress dinamiċi addizzjonali u jistgħu jiddestabilizzaw it-tagħbija.","Bażikament inaqqsu kwalunkwe moviment tal-pendlu.","Dejjem iżidu l-kapaċità tat-tagħbija nominali.","L-aċċelerazzjoni u l-forzi tal-ibbrejkjar iżidu t-tensjoni fuq il-krejn u l-bragi."],"k-sperrbereich":["X'għandek tiċċekkja qabel tbandal tagħbija f'żona kondiviża?","Impjegati oħra jaħdmu fil-qrib.","Jekk it-tagħbija taqbilx viżwalment mal-krejn.","Jekk iż-żona ta' periklu hijiex sigura u l-ebda nies ma jkunux f'riskju.","Jekk it-tagħbija tistax tinġarr kemm jista 'jkun 'il fuq minn kulħadd.","Il-mogħdijiet tad-dawran u tat-tagħbija għandhom ikunu ħielsa minn nies mhux protetti."],"k-stuetzen":["X'inhu kruċjali għal krejn mobbli b'outriggers?","Krejn jitqiegħed fuq art mimlija parzjalment.","Biss il-wisa' tat-triq.","Il-kulur tal-pjanċi ta 'appoġġ.","Bażi li ġġorr it-tagħbija kif ukoll appoġġ u distribuzzjoni tat-tagħbija skont l-istruzzjonijiet tal-installazzjoni u tal-manifattur.","L-installazzjoni għandha influwenza sinifikanti fuq l-istabbiltà, speċjalment fil-kundizzjonijiet tal-art li qed jinbidlu."],"k-wetter":["Buffura tar-riħ iġġiegħel it-tagħbija titbandal b'mod sinifikanti. X'inhu sewwa?","Inti taħdem barra.","Waqqaf il-moviment b'mod sikur u osserva kundizzjonijiet operattivi permissibbli.","Aċċellera malajr il-moviment.","Kompli neħħi t-tagħbija minkejja li taqbeż il-limiti tal-manifattur.","Il-movimenti tar-riħ u tat-tbandil jistgħu jiddestabilizzaw it-tagħbija u l-krejn; Il-limiti tal-applikazzjoni għandhom jiġu rispettati."],"k-freileitung":["X'japplika meta tuża krejnijiet ħdejn linji elettriċi overhead?","Boom jew tagħbija jistgħu jersqu lejn il-linja.","B'tagħbija mhux konduttiva, l-ispazji mhumiex importanti.","Iċċara ż-żona ta’ periklu u l-miżuri protettivi meħtieġa ma’ dawk responsabbli qabel ma tibda x-xogħol.","Jiddependi biss fuq ir-reazzjoni tal-operatur tal-krejn stess.","Hemm perikli minn kuntatt u flashover tal-vultaġġ; distanzi protettivi sikuri jew miżuri oħra huma meħtieġa."],"k-sichern":["X'tagħmel qabel ma titlaq mill-krejn?","Ix-xogħol jiġi interrott.","Ħalli t-tagħbija hang sospiża.","Ħalli l-krejn waħdu bis-sewqan jaħdem.","Niżżel it-tagħbija b'mod sigur u waħħal il-krejn skont l-istruzzjonijiet tat-tħaddim.","Tagħbijiet sospiżi m'għandhomx jitħallew mhux ikkontrollati; Il-krejn u t-tagħbija għandhom ikunu pparkjati b'mod sigur."],"k-lastanschlag":["Kif tkun taf jekk il-braga użata hijiex adattata?","It-tagħbija għandha titneħħa bl-użu ta 'ċinga ta' rfigħ.","F'termini ta 'immarkar, kapaċità ta' tagħbija, kundizzjoni u adattabilità għat-tip ta 'twaħħil.","Biss mill-kulur taċ-ċinga tal-irfigħ.","Għax diġà ntużat ilbieraħ.","Il-kapaċità tat-tagħbija u l-kundizzjoni għandhom ikunu biżżejjed, filwaqt li jitqiesu l-kundizzjonijiet tat-twaħħil."],"k-stopp":["Persuna tidħol għall-għarrieda fit-triq tat-tagħbija. X'qed tagħmel?","Il-krejn bħalissa qed imexxi tagħbija.","Waqqaf il-moviment b'mod sikur immedjatament u neħħi ż-żona ta' periklu.","Agħti sinjal ta' twissija u kompli ssuq.","Għolli t-tagħbija ogħla u issuq fuqha.","In-nies għandhom ikunu protetti mill-movimenti tat-tagħbija; Jekk ikun hemm periklu immedjat, il-moviment għandu jitwaqqaf."],"k-neuerkran":["Inti ser tirċievi krejn b'kontroll mhux magħruf. X'inhu sewwa?","Il-kontrolli huma differenti minn qabel.","Ipprova ċ-ċwievet tas-soltu jekk tissuspetta.","Ħalli lil xi ħadd ieħor mingħajr taħriġ isuq 'il quddiem.","Irċievi l-istruzzjoni meħtieġa relatata mal-apparat qabel l-użu indipendenti.","Anke operaturi tal-krejnijiet b'esperjenza jeħtieġu għarfien tal-kontrolli speċifiċi użati, tagħmir protettiv u limiti."],"a-kennzeichnung":["Kif tkun taf il-kapaċità ta 'tagħbija permissibbli ta' braga?","Trid tagħżel braga.","Ir-riħa tal-materjal.","Fuq l-immarkar xieraq u leġibbli tal-kapaċità tat-tagħbija u l-informazzjoni tal-manifattur.","Fuq it-tul tal-ħin tal-ħażna.","Il-kapaċità tat-tagħbija permissibbli hija determinata mill-kundizzjonijiet tat-tikkettar u tat-tħaddim."],"a-sichtpruefung":["Tinnota qatgħa ċara fiċ-ċinga tal-irfigħ. Kif tmur dwar dan?","Il-faxxa suppost iġorr tagħbija.","Tużax it-tejp u ibgħatha għall-ittestjar jew ir-rifjut.","Għatti l-qatgħa bit-tejp.","Użaha biss għal tagħbijiet partikolarment ħfief.","Bragi tat-tessuti bil-ħsara jistgħu jfallu u għandhom jiġu evalwati skont il-kriterji tar-rimi."],"a-neigungswinkel":["X'jiġri jekk l-angolu ta 'inklinazzjoni tal-fergħat tal-braga huwa akbar mill-vertikali?","Hanger b'żewġ fergħat jinfirex aktar.","Il-forzi tal-fergħa dejjem jonqsu.","Il-forzi tal-fergħa jibqgħu l-istess.","Il-forzi fil-fergħat jiżdiedu; L-angoli u l-kapaċitajiet tat-tagħbija permissibbli għandhom jiġu rispettati.","Hekk kif il-firxa tiżdied, il-forza tat-tensjoni għal kull linja ta 'appoġġ tiżdied."],"a-schwerpunkt":["Għaliex għandek bżonn tkun taf iċ-ċentru tal-gravità tat-tagħbija?","It-tagħbija hija mibnija b'mod irregolari.","Sabiex it-tagħbija tibqa’ stabbli meta titneħħa u ma tinqalebx bla kontroll.","Biex tagħżel il-kulur tal-bragi.","Sabiex it-tagħbija tkun tista 'tiddawwar aktar malajr.","Punti ta 'twaħħil sfavorevoli jew il-pożizzjoni taċ-ċentru tal-gravità jistgħu jwasslu għal twaqqigħ, jiżolqu jew inklinazzjonijiet inklinati."],"a-kantenschutz":["Ċinga ta 'rfigħ tinsab ma' tarf ta 'komponent li jaqtgħu. X'għandu jsir?","Il-komponent għandu jitneħħa.","Għolli t-tagħbija malajr qabel ma ċ-ċinturin ikun bil-ħsara.","Uża protezzjoni xierqa tat-tarf u ċċekkja t-tip ta 'twaħħil.","Naddaf il-wiċċ tat-tagħbija biss b'ċarruta.","Truf li jaqtgħu jistgħu jagħmlu ħsara lill-fibri ta 'appoġġ; it-tagħmir tal-braga għandu jkun protett kif xieraq."],"a-haken":["X'tagħti kas meta twaħħal braga?","Tuża ganċ tal-merkanzija.","Poġġi l-braga fuq in-naħa tal-ponta tal-ganċ.","Żomm il-flap tas-sigurtà miftuħ b'mod permanenti.","Tagħbija l-ganċ kif maħsub fil-bażi tal-ganċ u osserva l-apparat tas-sigurtà.","Tagħbija mhux permessibbli fuq il-ponta tal-ganċ u nuqqas ta 'żgurar jistgħu jwasslu biex tinfetaħ."],"a-knoten":["Tista 'tqassar ċinga ta' rfigħ li hija twila wisq b'għoqda?","It-tul tal-waqfien ma joqgħodx.","Le; Uża biss tip ta' braga adattat u approvat jew tagħmir ta' braga adattat.","Iva, jekk l-għoqda tinġibed sewwa ħafna.","Iva, sakemm it-tagħbija tkun bħalissa wieqfa.","L-għoqod jistgħu jdgħajfu b'mod sinifikanti l-bragi tat-tessuti u mhumiex permessi aġġustamenti improvizzati fit-tul."],"a-probehub":["Għaliex it-tagħbija inizjalment titneħħa bir-reqqa?","Trid tittrasporta b'mod sikur.","Sabiex tkun tista’ tivvjaġġa kemm jista’ jkun malajr.","Biex tiċċekkja l-pożizzjoni tal-bragi, l-istabbiltà u ċ-ċentru tal-gravità.","Minħabba li l-kapaċità tat-tagħbija tiżdied awtomatikament.","L-ewwel puplesija kkontrollata tgħin biex jinstabu waqfiet mhux korretti u pożizzjonijiet ta 'tagħbija mhux stabbli."],"a-lastweg":["Fejn in-nies jitħallew joqogħdu waqt li t-tagħbija tkun qed tiġi ttrasportata?","It-tagħbija titmexxa bi krejn.","Direttament taħt it-tagħbija b'elmu protettiv.","Fuq il-piż jekk jistgħu jżommu.","Barra miż-żona ta' periklu u mhux taħt tagħbijiet sospiżi.","Anke bi twaħħil bir-reqqa, għad hemm perikli minn tagħbijiet li jaqgħu jew jixxengel."],"a-haende":["Kif tevita korrimenti tat-tgħaffiġ meta tiftim?","It-tagħbija toqrob lejn il-wiċċ ta 'appoġġ.","Żomm l-idejn u s-saqajn 'il bogħod miż-żona tat-tgħaffiġ u uża għajnuniet xierqa.","Żomm it-tagħbija b'idejk vojta.","Stand bejn it-tagħbija u l-ħajt biex tikkoreġi l-pożizzjoni.","Jinqalgħu punti ta' niskata perikolużi bejn it-tagħbija u l-appoġġ."],"a-vierstraenge":["X'japplika għad-distribuzzjoni tat-tagħbija fuq sospensjoni b'erba' saqajn mingħajr kumpens tat-tagħbija?","Tagħbija riġida hija mwaħħla.","L-erba 'fergħat kollha inevitabbilment iġorru l-istess ammont.","Mingħajr prova ta' distribuzzjoni uniformi, il-kapaċità ta' ġarr ta' tagħbija ma tistax tintuża bħala stima ġenerali għal erba' linji ta' tagħbija bl-istess mod.","L-angolu ta 'inklinazzjoni huwa mbagħad irrilevanti.","It-tagħbija mhux ugwali tal-fergħa hija possibbli b'tagħbijiet riġidi; Id-disinn u l-kapaċità tat-tagħbija permissibbli għandhom iqisu dan."],"a-chemikalien":["X'japplika meta tuża bragi tat-tessuti f'kuntatt ma' kimiċi?","Qed taħdem b'likwidu mhux magħruf.","Il-kulur tal-faxxa juri b'mod affidabbli d-durabilità tiegħu.","Kull faxxa tat-tessut hija reżistenti għall-kimiċi kollha.","Iċċekkja d-durabilità u l-informazzjoni tal-manifattur; Tużax mezzi mhux xierqa.","Is-sustanzi kimiċi jistgħu jattakkaw il-bragi u mingħajr ma jiġu osservati jnaqqsu l-kapaċità tagħhom li jifilħu t-tagħbija."],"a-aufbewahrung":["Kif jinħażnu l-bragi wara l-użu?","Il-missjoni spiċċat.","Naddaf, niexef u protett mill-ħsara skond l-ispeċifikazzjonijiet tal-manifattur.","Imwaħħal mal-art taħt tagħbija mhux protetta.","Fuq kull ganċ ta' barra li jaqtgħu.","Ħażna xierqa tipprevjeni l-użu prematur u tagħmel l-ispezzjoni viżwali aktar faċli."],"a-auswahl":["X'għandu jitqies b'mod partikolari għal tagħbijiet sensittivi jew bit-truf li jaqtgħu?","Komponent tal-magna miżbugħa għandu jiġi mċaqlaq.","Biss il-veloċità tat-trasport.","Bragi xierqa u miżuri protettivi għall-wiċċ tat-tagħbija u t-truf.","Irrispettivament mit-tagħbija, dejjem l-istess kejbil tal-azzar.","It-tip ta 'twaħħil u materjal għandhom jaqblu mal-ġeometrija, il-wiċċ u l-periklu."],"a-abstimmung":["L-operatur tal-krejn m'għandu l-ebda dehra tiegħek. Kif tagħti struzzjonijiet?","Inti assenjat bħala attakkant.","Int tħawwad bir-rieda sakemm jibda moviment.","Inti sempliċiment tagħti sejħa waħda u walk away.","Permezz ta' sinjali miftiehma b'mod ċar jew komunikazzjoni affidabbli oħra.","L-attakkanti u l-operaturi tal-krejnijiet għandhom jikkomunikaw b'mod ċar; Jekk ma jkunx ċar, il-moviment għandu jitwaqqaf."],"b-qualifikation":["X'għandha bżonn persuna biex tħaddem b'mod sikur excavator idrawliku waqt it-tħaddim?","Persuna ġdida għandha tieħu f'idejha xogħol fuq is-sit tal-kostruzzjoni.","Kwalifiki xierqa, struzzjoni relatata mal-apparat u assenjazzjoni meħtieġa.","Liċenzja tas-sewqan tal-karozza biss.","Biss osservazzjoni mgħaġġla tal-operazzjoni.","Min iħaddem għandu jiżgura l-kwalifiki meħtieġa u jagħti struzzjonijiet lill-operatur kif xieraq għall-kompitu."],"b-pruefung":["X'inhu inkluż fl-ispezzjoni ta 'kuljum tal-magni?","Inti tieħu f'idejha excavator.","Iċċekkja l-kulur taż-żebgħa u t-tapizzerija tas-sedil.","Spezzjoni viżwali u testijiet funzjonali skont l-istruzzjonijiet tat-tħaddim, pereżempju għal tnixxijiet u ħsara.","Mexxi l-boom b'veloċità sħiħa sakemm tieqaf.","Ħsara lill-idrawlika, ix-chassis u l-apparati tas-sigurtà jistgħu jwasslu għal inċidenti serji."],"b-leitungen":["X'jeħtieġ li jkun magħruf dwar il-pajpijiet taħt l-art qabel it-tħaffir?","Għandek ħaffer foss.","Biss il-fond approssimattiv tal-fossa tat-tħaffir ippjanata.","Il-kulur tal-marki 'l fuq mill-art huwa biżżejjed.","Iċċara l-post tal-linji possibbli u tiddetermina miżuri ta 'sigurtà u esplorazzjoni xierqa.","Il-pajpijiet tal-elettriku, tal-gass jew tal-ilma jista’ jkollhom konsegwenzi ta’ theddida għall-ħajja jekk ikunu mħassra."],"b-schwenkbereich":["Kif tipproteġi n-nies fiż-żona tal-iswing tal-iskavatur?","Inti aqbad materjal mal-boom.","Iċċekken jew assigura ż-żona ta' periklu u żomm lin-nies 'il bogħod.","Qabel iddawwar, ċċaqlaq il-pala bil-mod.","Issuq fuq iż-żona fuq l-irjus.","Is-sovrastruttura li ddur u l-implimenti joħolqu perikli ta’ tgħaffiġ u impatt."],"b-boeschung":["X'inhu importanti meta taħdem ħdejn it-tarf ta 'ħofra ta' tħaffir?","L-iskavatur ikun wieqaf fuq art stabbilita jew mimlija.","Il-fond tat-tħaffir waħdu jiddetermina t-tqegħid permissibbli.","Oqgħod attent għall-kapaċità li ġġorr it-tagħbija u s-sigurtà tat-tarf kif ukoll id-distanzi meħtieġa skont il-valutazzjoni tar-riskju.","Issuq kemm jista 'jkun qrib it-tarf biex tiffranka l-firxa.","Jekk ma jkunx hemm spazju biżżejjed jew art stabbli, il-moll jista 'jfalli u l-magna tista' taqa'."],"b-standsicherheit":["Għaliex l-inklinazzjoni u l-art huma kruċjali għall-użu?","Is-sit tal-kostruzzjoni jinsab fuq inklinazzjoni.","Il-magna hija ugwalment stabbli fuq kwalunkwe wiċċ.","L-undercarriages tracked jeliminaw kwalunkwe riskju ta' twarrib.","Irregolarità u għoljiet jistgħu jaffettwaw l-istabbiltà; Osserva l-limiti tal-applikazzjoni.","L-istabbiltà u s-sigurtà tat-twaddib tiddependi fuq l-art, it-tagħmir, it-tagħbija u l-pożizzjoni tal-magna."],"b-wechselgeraet":["X'tiċċekkja wara li tbiddel barmil tal-iskavatur bl-użu ta 'quick coupler?","Ġie installat attachment ġdid.","Jekk huwiex imsakkar u mwaħħal sew skont l-istruzzjonijiet tat-tħaddim.","Eżatt jekk il-kulur tal-pala jaqbilx.","Jekk l-idrawlika taħdem bil-kwiet kemm jista 'jkun.","Serraturi difettużi jistgħu jikkawżaw aċċessorji li jaqgħu."],"b-heben":["X'għandek tagħti attenzjoni meta jerfgħu tagħbija mdendla liberament bi excavator?","L-iskavatur jintuża għall-operazzjonijiet ta 'rfigħ.","Il-forza tas-soltu tat-tħaffir biss hija deċiżiva.","Osserva t-tagħbija ta 'rfigħ permissibbli, punti ta' twaħħil adattati u tagħmir protettiv preskritt.","It-tagħbija tista 'tiġi hooked fuq is-snien tal-barmil.","L-irfigħ huwa permess biss fil-kundizzjonijiet ta' tħaddim maħsuba b'tagħmir xieraq."],"b-rueckwaerts":["Trid ireġġa' lura, imma ma tistax tara t-triq. X'inhu sewwa?","Ħaddiema oħra huma fil-qrib.","Issuq b'attenzjoni mingħajr viżibilità.","Ħonk biss u kompli ssuq.","Waqqaf, tiżgura l-viżibilità u ż-żona ta 'periklu jew organizza struzzjonijiet xierqa.","It-treġġigħ lura m'għandux jipperikola lin-nies; viżibilità limitata teħtieġ miżuri addizzjonali."],"b-kabel":["L-isplużjoni tista 'tqarreb linja ta' enerġija fl-għoli. X'qed tagħmel?","Inti taħdem fuq sit ta 'kostruzzjoni strett.","Iċċara ż-żona ta' periklu u miżuri protettivi xierqa ma' dawk responsabbli minn qabel.","Injora l-linja jekk il-boom huwa miżbugħ.","Iċċaqlaq biss il-boom partikolarment malajr.","Perikli elettriċi jinqalgħu minn kuntatt u flashover; distanzi sikuri u miżuri protettivi huma meħtieġa."],"b-verlassen":["Kif tipparkja l-iskavatur qabel ma titlaq?","Inti tieħu pawża.","Ħalli l-boom f'wiċċ l-ilma liberament.","Poġġi t-tagħmir tax-xogħol b'mod sikur u waħħal il-magna kontra moviment u użu mhux awtorizzat.","Ħalli l-magna taħdem u l-kabina miftuħa.","Tagħmir tax-xogħol imnaqqas u protezzjoni kontra moviment mhux intenzjonat inaqqsu r-riskju ta 'inċidenti."],"b-hydraulik":["Tinnota żejt idrawliku taħt pressjoni għolja fuq linja bil-ħsara. X'inhu sewwa?","Linja qed tnixxi.","Ħoss it-tnixxija b'idejk.","Waħħal morsa ġdida taħt pressjoni.","Itfi l-magna b'mod sikur, ħalli l-pressjoni titnaqqas u rranġa biex isiru tiswijiet minn persunal speċjalizzat awtorizzat.","Fluwidu idrawliku taħt pressjoni għolja jista 'jikkawża korrimenti serji; qatt ma tiċċekkja għal tnixxijiet bl-idejn."],"b-unterbau":["X'inhu l-periklu tas-sewqan fuq uċuħ instabbli?","L-art hija ratba wara x-xita.","Il-magna tista 'tinżel, tiżżerżaq jew tinqaleb.","Is-sewqan awtomatikament isir usa '.","Dan jagħmel il-firxa tad-dawran aktar sigura.","Kapaċità ta 'tagħbija insuffiċjenti tista' tfixkel b'mod sinifikanti l-istabbiltà u s-sikurezza tas-sewqan."],"b-arbeitsgeraet":["Jista' xi ħadd jaħdem taħt għodda mgħollija?","Persuna trid tikkontrolla xi ħaġa taħt il-pala.","Iva, meta l-magna tkun idling.","Le, mhux mingħajr l-appoġġ u s-sigurtà meħtieġa tat-tagħmir tax-xogħol.","Iva, jekk il-persuna tkun liebes elmu tas-sigurtà.","Tagħmir idrawliku jista 'jegħreq; Ix-xogħol ta’ manutenzjoni jeħtieġ tagħmir ta’ xogħol sigur."],"b-geraeteart":["Inti taqleb minn excavator idrawliku għal wheel loader. X'inhu meħtieġ?","L-operat u l-imġieba tal-moviment huma differenti.","Biss l-istess xedd tas-saqajn.","Test drive mingħajr struzzjonijiet.","Il-kwalifika jew l-istruzzjoni meħtieġa għat-tip ta 'magna ġdida.","Il-kwalifika għandha taqbel mat-tip ta 'magna użata u r-rekwiżiti operattivi speċifiċi."],"g-neigung":["Qed issuq forklift mgħobbi fuq inklinazzjoni. X'inhu importanti?","Ir-rotta għandha gradjent ċara.","Dejjem ggwida t-tagħbija għan-niżla, anke jekk tkun tqila.","Iggwida t-tagħbija għat-telgħa u osserva l-linji gwida operattivi għas-sewqan fuq inklinazzjonijiet.","Irrispettivament mid-direzzjoni tal-vjaġġ, għolli l-furketta sal-massimu.","Fl-inklinazzjonijiet u l-inżul, it-tagħbija għandha dejjem tinġarr għat-telgħa; Il-vettura u l-istruzzjonijiet tat-tħaddim għandhom jiġu osservati."],"g-gabelabsenken":["Għaliex il-furketta trid titbaxxa meta tipparkja?","Il-forklift huwa pparkjat għal waqfa.","Sabiex ħaddieħor ikun jista’ juża l-furketta biex jitla’.","Sabiex il-furketta tibqa’ aktar viżibbli mill-bogħod.","Sabiex l-irfigħ tat-tagħbija ma joħloqx riskju bla bżonn ta 'tgerbib jew korriment.","L-apparati tal-immaniġġjar tat-tagħbija mnaqqsa jnaqqsu r-riskju ta 'inċidenti minħabba frieket li joħorġu 'l barra jew mhux assigurati."],"g-fahrerwechsel":["Kollega jixtieq jissellef il-forklift. X'għandu jkun preżenti?","Il-kollega għandu biss permess verbali mingħandek.","Għandu jkollu l-kwalifiki meħtieġa u mandat ta' kumpanija.","L-inkarigu tiegħek awtomatikament japplika għalih ukoll.","Liċenzja tas-sewqan tal-karozza privata hija biżżejjed għal kull negozju.","Tmexxija indipendenti hija marbuta mal-adegwatezza personali, it-taħriġ, il-kwalifiki u l-inkarigu operattiv."],"g-ladungssicherung":["Pallet fih kaxxi maħlula u f'munzelli. X'inhu sewwa?","Kaxxa tal-kartun tista' taqa' 'l isfel waqt is-sewqan.","Żgura t-tagħbija kontra ż-żliq u l-waqgħa qabel it-trasport.","Issuq biss bil-mod fuq art partikolarment irregolari.","Ikkumpensa għal kaxxi maħlula b'pożizzjoni ogħla tal-furketta.","It-tagħbija għandha tkun stabbli u assigurata kontra l-waqgħa qabel ma tiġi ttrasportata mat-trakk industrijali."],"g-bodenbelastung":["Quddiemek hemm kutra b'kapaċità limitata li ġġorr it-tagħbija. Kif tiddeċiedi?","Ir-rotta twassal fuq livell intermedju.","Oqgħod attent biss għall-piż tat-trakk mingħajr tagħbija.","Iċċara t-tagħbija tal-art permissibbli għal forklifts u tagħbijiet.","Issuq b'momentum sabiex is-saqaf ikun taħt tagħbija għal perjodu iqsar ta 'żmien.","Dak li huwa rilevanti huwa l-istress totali attwali fuq iż-żona, inklużi l-vettura, it-tagħbija u l-influwenzi dinamiċi."],"g-verkehrswege":["Passaġġ immarkat jaqsam it-triq tiegħek. X'inhu sewwa?","Il-persuni mexjin jistgħu jaċċessaw il-qsim fi kwalunkwe ħin.","Inti tista 'dejjem titlob prijorità mal-ħorn.","Inti titħalla ssuq minn fuq il-marka mingħajr ma tiġi osservat.","Aġġusta l-veloċità tiegħek, oqgħod attent għall-persuni mexjin u kompli ssuq biss meta t-triq tkun ċara.","Ir-rotot tat-traffiku għandhom jiġu misjuqa b'konsiderazzjoni għan-nies; Is-sinjali ta' twissija ma jissostitwixxux viżibilità sigura u rotta ċara."],"g-parkbremse":["Inti tipparkja forklift fuq art livell. Dak x'jinkludi?","Trid tħalli s-sedil tas-sewwieq għal diversi minuti.","Ipparkja, applika l-brejk tal-ipparkjar u sigur kontra użu mhux awtorizzat.","Ħalli l-vettura biss f'pożizzjoni newtrali.","Ħalli l-furketta fl-għoli tar-ras biex ħadd ma jmissha.","Qabel ma jitlaq, it-trakk għandu jitwaqqaf b'mod sikur u mwaħħal kontra moviment mhux intenzjonat."],"g-typenschild":["Liema informazzjoni torbot meta niġu għat-tagħbija fuq forklift truck?","Trid tieħu magna tqila.","Il-kapaċità tat-tagħbija stmata bbażata fuq id-daqs tal-vettura.","L-informazzjoni tal-manifattur fid-dijagramma tal-kapaċità tat-tagħbija jew tat-tagħbija.","Il-piż tal-aħħar pallet trasportat.","It-tagħbija permissibbli hija determinata mill-informazzjoni tal-manifattur u tiddependi, fost affarijiet oħra, fuq iċ-ċentru tat-tagħbija u l-għoli tal-irfigħ."],"g-tore":["Inti tersaq lejn passaġġ baxx bil-forklift. X'qed tiċċekkja?","Hemm tagħbija towering fuq il-vettura.","Jekk il-passaġġ inkluż it-tagħbija u t-twaħħil huwiex possibbli b'mod sikur.","Biss l-għoli tal-karru tal-furketta mingħajr tagħbija.","Jekk tistax issuq aktar malajr qabel ma jagħlaq il-bieb.","Qabel il-passaġġi, għandhom jitqiesu l-għoli u l-wisa' ċari kif ukoll id-dimensjonijiet tat-tagħbija u tal-vettura."],"g-reifen":["Matul il-kontroll ta' kuljum tiegħek issib tajer bil-ħsara. X'qed tagħmel?","Ħsara rilevanti għas-sigurtà hija viżibbli fuq it-tajer.","Issuq bil-mod sal-appuntament ta’ manutenzjoni regolari tiegħek.","Iżżid il-pressjoni tat-tajers u tibqa’ ssuq.","Inti ma tieħux il-vettura fis-seħħ u tirrapporta l-ħsara.","Tajers bil-ħsara jistgħu jfixklu l-istabbiltà u l-immaniġġjar; id-difett għandu jiġi ċċarat qabel l-użu."],"h-absperren":["L-impjegati jgħaddu minn taħt il-pjattaforma tax-xogħol tiegħek. X'inhu meħtieġ?","Hemm periklu minn għodod li jaqgħu.","Żona protettiva jew ristretta xierqa taħt il-post tax-xogħol.","Avviż biss meta tgħaddi l-ewwel.","Aħżen l-għodda kemm jista 'jkun 'il bogħod mit-tarf tal-basket.","Żona tax-xogħol taħt stazzjonijiet tax-xogħol elevati għandha tkun assigurata kontra l-periklu minn partijiet li jaqgħu."],"h-werkzeuge":["Kif tittrasporta l-għodda fil-basket tax-xogħol?","Hemm bżonn ta 'diversi għodod żgħar fl-għoli.","Poġġihom laxk fuq il-puġġaman sabiex ikunu jistgħu jintlaħqu faċilment.","Aħżen u waħħalhom b'tali mod li ma jaqgħux 'l isfel jew ma jfixklux it-tħaddim.","Waħħal ma 'barra tal-puġġaman fil-but tiegħek.","Oġġetti sfużi jistgħu jaqgħu u jipperikolaw lin-nies; ħażna sigura hija meħtieġa."],"h-abstuetzung":["Appoġġ joqgħod fuq għata tat-tappiera. X'għandu jiġi ċċekkjat?","Trid tgħolli l-pjattaforma.","Kun żgur li l-għatu huwa niexef.","Jekk it-tagħbija tistax tiġi assorbita b'mod sikur f'dak il-punt.","Jekk l-appoġġi l-oħra m'għandhomx għalfejn jintużaw.","Is-sotto-ħamrija u ż-żoni ta' kuntatt għandhom ikunu kapaċi jassorbu b'mod sikur il-forzi ta' appoġġ; Il-kopertura għandhom jiġu evalwati separatament."],"h-notaus":["Meta għandu jintuża l-apparat ta 'waqfien ta' emerġenza?","Iseħħ immedjatament moviment perikoluż.","Biss fi tmiem xift regolari.","Għall-waqfien f'periklu akut skond l-istruzzjonijiet tat-tħaddim.","Bħala sostitut għat-tnaqqis ippjanat.","Il-waqfien ta 'emerġenza jintuża biex jevita l-periklu, mhux il-kontroll tas-soltu jew għeluq normali."],"h-schraegstellung":["It-twissija tal-inklinazzjoni tal-palk twieġeb. Kif tirreaġixxi?","Il-magna hija fuq wiċċ inklinat.","Int tinjora t-twissija f'għoli tax-xogħol baxx.","Minkejja t-twissija, issuq għall-ogħla pożizzjoni ta 'rfigħ.","Tieqaf u ġġib l-istadju f'kundizzjoni sigura skont l-istruzzjonijiet tal-manifattur.","Twissijiet ta 'mejjel jistgħu jindikaw stabbiltà inadegwata; movimenti ulterjuri m'għandhomx iżidu l-periklu."],"h-umgebung":["X'għandu jiġi organizzat meta twaqqaf ħdejn żona tat-traffiku?","Il-vetturi jistgħu jmissu l-palk.","Protezzjoni kontra ħabtiet u gwida xierqa tat-traffiku.","Itbandal il-basket tax-xogħol kemm jista' jkun fuq it-triq.","Sejħa ta' twissija biss qabel ma tibda.","Il-pjattaformi tax-xogħol mill-ajru għandhom ikunu protetti kontra l-ħabtiet mal-utenti tat-triq; l-installazzjoni għandha tkun assigurata kif xieraq."],"h-ueberlast":["It-twissija ta' tagħbija żejda fil-basket tiġi attivata. X'qed tagħmel?","Ġew mistiedna għodod addizzjonali.","Temm ix-xogħol b'veloċità ogħla.","Stabbilixxi t-tagħbija permissibbli tal-basket u segwi l-istruzzjonijiet tal-manifattur.","Itfi s-sinjal ta' twissija b'mod permanenti.","It-tagħbija massima permissibbli fuq il-basket, inklużi n-nies u l-materjal, m'għandhiex tinqabeż."],"h-quetschen":["Issuq il-basket mill-qrib taħt saqaf. Liema periklu huwa partikolarment importanti?","Fadal ftit spazju fuq il-basket.","Ikklampjar jew tgħaffiġ bejn il-basket u l-istruttura.","Li l-magna tikkonsma aktar fjuwil.","Li d-direzzjoni tal-vjaġġ dejjem ireġġa 'lura awtomatikament.","Spazji stretti 'l fuq jew ħdejn il-basket tax-xogħol jistgħu jikkawżaw korrimenti serji ta' tgħaffiġ."],"h-stromausfall":["L-istadju jibqa 'f'għoli kbir mingħajr drive prinċipali. X'inhu sewwa?","Il-kontroll normali tal-basket m'għadux jirrispondi.","Inti titla 'l isfel mill-boom mingħajr sigurtà.","Tistenna sa tmiem ix-xift tiegħek mingħajr ma tkun infurmat.","Ibda s-salvataġġ ippreparat billi tuża nies imħarrġa u tbaxxija ta 'emerġenza.","Salvataġġ sikur irid ikun ippjanat għal tfixkil; Nies imħarrġa għandhom ikunu jafu l-funzjonijiet ta 'emerġenza."],"h-transportstellung":["Kif tħejji t-triq għal trasport?","Il-pjattaforma tax-xogħol mill-ajru titgħabba fuq vettura adattata.","Ġib il-boom u l-pjattaforma fil-pożizzjoni tat-trasport skont l-istruzzjonijiet tat-tħaddim.","Orbot il-pjattaforma kemm jista 'jkun.","Ħalli l-appoġġi estiżi sabiex jieħu aktar spazju.","Il-pożizzjoni tat-trasport preskritta u l-iżgurar tat-tagħbija huma bbażati fuq l-ispeċifikazzjonijiet tal-manifattur u tat-trasport."],"k-bremsprobe":["X'juri test funzjonali tal-brejk tal-krejn qabel l-użu?","Trid tkun tista 'żżomm tagħbija b'mod sikur.","Jekk il-brejk jieqafx u jżommx il-moviment kif maħsub.","Eżatt jekk id-dawl tal-kabina jaħdem.","Jekk il-ganċ jistax awtomatikament iżomm tagħbija.","Qabel l-użu, il-funzjonijiet rilevanti għas-sigurtà għandhom jiġu kkontrollati skont l-ispeċifikazzjonijiet."],"k-schraegzug":["Tista 'tiġbed tagħbija fuq il-ġenb f'angolu mal-krejn?","Il-ganċ mhuwiex vertikalment 'il fuq mit-tagħbija.","Iva, jekk il-krejn għad għandu riżerva tat-tagħbija.","Le, it-tagħbijiet m'għandhomx jinġibdu bl-użu ta' ġbid djagonali mhux permessibbli.","Iva, jekk il-bragi huma partikolarment qosra.","Il-ġbid djagonali jista 'jikkawża movimenti mhux ikkontrollati u tensjoni addizzjonali fuq il-krejn u l-bragi."],"k-verhakt":["Tagħbija mdendla fuq is-sottostruttura. X'inhu sewwa?","Ir-reżistenza tinħass waqt l-irfigħ.","Int tibqa’ tgħolli sakemm toħroġ.","Int tmexxi t-tagħbija lejn il-ġenb b'daqqa.","Tieqaf u tneħħi l-irbit jew l-imblukkar mingħajr periklu.","Tagħbijiet mwaħħla m'għandhomx jinqatgħu bil-forza, peress li jistgħu jinqalgħu forzi inaċċettabbli."],"k-anzuheben":["X'tiċċekkja meta jerfgħu tagħbija sospiża għall-ewwel darba fil-qosor?","It-tagħbija tgħolli ftit ċentimetri mill-art.","Kemm jekk tiddendel fil-bilanċ u jekk il-waqfien huwa sigur.","Jekk persuna tistax tpoġġi lilha nnifisha direttament taħt it-tagħbija.","Jekk il-krejn isirx aktar stabbli billi ddawwar malajr.","L-irfigħ ikkontrollat ​​fil-qosor jintuża biex jiċċekkja t-twaħħil, il-bilanċ u l-imġieba tat-tagħbija bla periklu."],"k-lastweg":["Fejn għandha tkun ir-rotta tat-trasport ta 'tagħbija tal-krejn?","Diversi postijiet tax-xogħol jinsabu taħt il-mogħdija tat-tagħbija possibbli.","Jekk possibbli, fuq il-postijiet tax-xogħol okkupati.","Fi triq ippjanata u ċara mingħajr nies f'riskju.","Dejjem dijagonalment mill-aktar żona traffikuża.","Ir-rotot tat-tagħbija għandhom ikunu organizzati b'tali mod li n-nies ma jkunux ipperikolati minn tagħbijiet sospiżi."],"k-signalverlust":["Il-konnessjoni tar-radju mal-marixxall tkisser. X'qed tagħmel?","Ma tistax tara l-mogħdija tat-tagħbija innifsu.","Tkompli l-moviment bil-mod.","Inti esperimentalment jitbandal fid-direzzjoni preċedenti.","Twaqqaf il-moviment sakemm ikun hemm fehim ċar u sigur.","Jekk ikun hemm nuqqas ta 'komunikazzjoni, il-moviment tat-tagħbija konfuż jista' ma jkomplix."],"k-haken":["Il-ganċ tas-sigurtà ma jagħlaqx b'mod affidabbli. X'inhu sewwa?","Waqt l-ispezzjoni, jiġi nnutat għeluq difettuż.","L-iżball għandu jiġi kkoreġut professjonalment qabel aktar użu.","Int torbot issikkat il-qafla b'irbit tal-kejbil.","Int tuża l-ganċ biss għal tagħbijiet ħfief.","Apparati difettużi li jassiguraw fuq ganċijiet tat-tagħbija jistgħu jwasslu biex il-bragi jinqalgħu u għandhom jiġu rimedjati."],"k-zugrichtung":["X'inhu importanti għall-appoġġ vertikali ta 'tagħbija?","It-tagħbija għandha titneħħa minn magna.","Il-ganċ tal-krejn għandu jkun allinjat fuq iċ-ċentru tal-gravità tat-tagħbija.","Il-ganċ għandu jitqiegħed kemm jista 'jkun lejn il-ġenb.","It-tagħbija għandha tiġi mbuttata qabel ma tneħħi.","Effett tal-forza li jkun vertikali kemm jista 'jkun 'il fuq miċ-ċentru tat-tagħbija jevita forzi laterali mhux permessi u tbandil bla kontroll 'il barra."],"k-wartung":["Ħoss tat-tħin mhux tas-soltu jiġi nnutat fuq il-krejn. Kif tmur dwar dan?","Il-ħoss iseħħ meta jerfa'.","Għatti l-istorbju permezz ta 'veloċità ogħla.","Waqqaf l-operazzjonijiet b'mod sikur, irrapporta d-difetti u ssolvihom.","Kompli taħdem mingħajr avviż sal-waqfa.","Bidliet notevoli jistgħu jindikaw ħsara rilevanti għas-sikurezza u jeħtieġu spezzjoni."],"k-absetzen":["X'għandu jkun garantit meta titbaxxa tagħbija tal-krejn?","Tagħbija tqila titqiegħed fuq wiċċ.","It-tagħbija tista' tkun mhux assigurata fuq wiċċ inklinat.","Slings jitneħħew waqt li jkun għadu f'wiċċ l-ilma.","It-tagħbija hija stabbli u assigurata kontra t-twaddib jew it-tidwir.","It-tagħbija tista' tiġi rilaxxata biss mill-irkaptu tal-braga wara li tkun ġiet imwaqqfa b'mod sikur u tkun ġiet stabbilita l-istabbiltà."],"l-schwerpunkt":["Għaliex iċ-ċentru tal-gravità jrid ikun magħruf qabel jolqot?","Magna b'forma asimetrika għandha tiġi ttrasportata.","Sabiex it-tagħbija tibqa' kemm jista' jkun ibbilanċjata meta rfigħ.","Sabiex il-bragi jkunu jistgħu jintgħażlu sakemm ikun mixtieq.","Sabiex il-kapaċità tat-tagħbija permissibbli ma taqdix rwol.","Il-pożizzjoni taċ-ċentru tal-gravità tinfluwenza d-distribuzzjoni tat-tagħbija u l-bilanċ sikur meta rfigħ."],"l-etikett":["Ċinga tal-irfigħ m'għandhiex tikketta tal-kapaċità tat-tagħbija li tinqara. X'inhu sewwa?","L-immarkar sar mhux rikonoxxibbli.","Stima l-kapaċità tat-tagħbija bbażata fuq il-kulur.","Tużax iċ-ċinga ta' l-irfigħ qabel ma tkun intweriet b'mod ċar l-adattabilità tagħha.","Uża ċ-ċinturin darba biss għal tagħbijiet żgħar.","Marki xierqa huma meħtieġa għall-bragi; Kapaċità ta 'ġarr mhux spjegata tipprekludi għażla sigura."],"l-kantenschutz":["Faxxa tat-tessut tinsab fuq tarf ta 'l-azzar li jaqtgħu. X'inhu meħtieġ?","It-tagħbija għandha truf li jaqtgħu.","Iġbed il-faxxa kemm jista 'jkun sewwa mingħajr protezzjoni.","Wettaq il-puplesija aktar malajr.","Uża protezzjoni xierqa tat-tarf jew tagħmir ieħor adattat għall-imbraga.","Truf li jaqtgħu jistgħu jagħmlu ħsara jew jaqtgħu bragi tat-tessuti; hija meħtieġa protezzjoni xierqa."],"l-spreizwinkel":["Kif angolu akbar ta 'inklinazzjoni jaffettwa t-tagħbija fuq bragi?","Tagħbija titneħħa bl-użu ta' żewġ ħbula immejla.","F'angoli inqas favorevoli, il-forzi fil-fergħat jistgħu jiżdiedu.","Il-forzi tal-fergħa jisparixxu.","L-angolu m'għandu l-ebda influwenza fuq l-istress.","B'angolu ta 'waqfien inqas favorevoli, il-forzi għal kull fergħa jistgħu jiżdiedu; It-tabelli tal-kapaċità tat-tagħbija għandhom jiġu osservati."],"l-knoten":["Jista 'jqassar ħabel tal-braga kif mixtieq bl-użu ta' għoqda?","Il-ħabel huwa twil wisq għat-tagħbija ppjanata.","Iva, għoqda stretta ttejjeb il-kapaċità tat-tagħbija.","Le, uża biss metodi ta' tqassir u ankraġġ approvati.","Iva, jekk l-għoqda tkun assigurata bit-tejp.","L-għoqod mhux permessi jdgħajfu l-bragi u jbiddlu l-kapaċità tat-tagħbija permissibbli tagħhom."],"l-zeichen":["X'japplika għall-komunikazzjoni mal-persuna li tħaddem il-krejn?","Il-mogħdija tat-tagħbija hija parzjalment mgħottija.","Diversi nies jagħtu sinjali differenti fl-istess ħin.","Jintużaw sinjali ċari u miftiehma qabel.","Il-komunikazzjoni qatt ma hija meħtieġa bil-krejnijiet tar-radju.","Sinjali ċari u responsabbiltajiet ċari jipprevjenu movimenti perikolużi żbaljati."],"l-sichtpruefung":["Meta l-bragi għandhom jiġu ċċekkjati għal difetti viżibbli?","Trid tuża katina tal-braga.","Qabel l-użu, oqgħod attent għal kwalunkwe ħsara viżibbli esternament.","Biss jekk ikun diġà ġara inċident.","Darba biss meta nxtara l-ewwel darba.","Qabel kull użu, il-kundizzjoni tax-xogħol bla periklu għandha tiġi vvalutata; Ħsara viżibbli tipprekludi użu sigur."],"l-drehung":["Tagħbija mgħollija tibda ddur bla kontroll. X'qed tagħmel?","It-tagħbija timxi fil-mogħdija tat-tagħbija.","Tpoġġi idejk bejn it-tagħbija u l-ħajt.","Tpoġġi lilek innifsek taħt il-piż u żżommu.","Int iżżomm id-distanza tiegħek u tħalli l-moviment jieqaf b'mod ikkontrollat.","Movimenti ta 'tagħbija mhux ikkontrollati joħolqu perikli ta' tgħaffiġ u impatt; In-nies iridu jħallu ż-żona ta' periklu."],"l-ablegen":["Meta l-bragi jistgħu jitneħħew mit-tagħbija?","It-tagħbija titqiegħed fuq trestles.","Jekk it-tagħbija hija stabbli u mwaħħla kontra l-qlib jew it-tidwir.","Hekk kif tmiss l-art għall-ewwel darba, irrispettivament mill-pożizzjoni tagħha.","Filwaqt li għadek iddur biex tiffranka l-ħin.","Il-bragi jistgħu jitneħħew biss wara li jkunu ġew imwaqqfa b'mod sigur u stabbli."],"l-ketten":["Braga tal-katina għandha ħolqa milwija ħafna. X'qed tagħmel?","Il-ħsara hija viżibbli anke qabel l-irfigħ.","Kebbeb iż-żona bil-ħsara bil-wajer.","Neħħi l-katina mill-użu u ċċekkjaha professjonalment.","Għolli biss it-tagħbija nofs l-għoli.","Links tal-katina deformati huma ħsara viżibbli li tista 'tipprevjeni l-użu sikur."],"b-einweiser":["X'inhu importanti meta l-viżibilità mill-iskavatur hija limitata?","Parti mill-bini taħbi ż-żona tas-sewqan.","Miżuri viżwali jew istruzzjoni xierqa u komunikazzjoni ċara.","Ara biss il-barnuża.","Issuq fiż-żona li jdur minkejja li tkun inviżibbli.","Jekk il-viżibilità hija ristretta, il-perikli għandhom jiġu evitati permezz ta' miżuri organizzattivi u tekniċi addizzjonali."],"b-aushub":["Fejn jista 'jinħażen materjal skavat ħdejn ħofra tal-kostruzzjoni?","It-tarf tal-fossa m'għandux jitqiegħed f'riskju addizzjonali.","Pile up direttament fuq it-tarf sabiex driveways jibqgħu ċari.","Aħżen f'distanza sigura biżżejjed u skont l-ispeċifikazzjonijiet tas-sit tal-kostruzzjoni.","Poġġi fuq shoring maħlul mingħajr aktar testijiet.","Materjal skavat jista 'jipperikola l-imbankijiet u l-puntar minħabba tagħbijiet addizzjonali; Id-distanzi tas-sigurtà għandhom jinżammu."],"b-personen":["In-nies jitħallew jibqgħu fiż-żona tat-tbandil waqt li l-iskavatur ikun miexi?","Persuna trid tkejjel waqt il-panning.","Iva, sakemm tilbes elmu tas-sigurtà.","Iva, jekk l-iskavatur jitbandal bil-mod.","Le, iż-żona ta 'periklu għandha tkun ċara qabel il-moviment.","Hemm riskju ta 'tgħaffiġ serju u korrimenti ta' impatt fiż-żona tad-dawrien; iż-żona għandha tinżamm ċara."],"b-ladung":["Kif tittrasporta materjal b'mod sikur b'wheel loader?","Pala mimlija għandha tkun misjuqa madwar il-bitħa.","B'pożizzjoni ta 'trasport baxxa xierqa u mogħdija ċara.","Bil-pala mgħollija għal viżibilità aħjar.","B'bibien miftuħa u angolu ta 'l-istering qawwi.","Pożizzjoni xierqa tat-trasport tnaqqas ir-riskju ta 'qlib u ttejjeb l-istabbiltà tas-sewqan."],"b-anbaupruefung":["X'tiċċekkja wara li tgħaqqad attachment?","Ġiet imwaħħla pala ġdida.","Biss l-indafa taż-żebgħa.","L-illokkjar sikur u l-funzjoni skond l-istruzzjonijiet tat-tħaddim.","Eżatt jekk l-apparat jidher l-istess minn barra.","Serraturi mhux korretti fuq kick couplers jistgħu jwasslu għal rilaxx mhux intenzjonat ta 'aċċessorji."],"b-einstieg":["Kif tidħol fil-kabina tal-iskavatur b'mod sikur?","Il-passi huma maħmuġin wara x-xita.","Tlugħ fuq il-kabina permezz tal-boom.","Ikseb fuq il-caterpillars f'qabża waħda.","Uża turġien u imqabad magħżula u naddaf passi maħmuġin.","Tlugħ addattat u punti ta 'żamma siguri jnaqqsu r-riskju li jiżolqu u jaqgħu."],"b-graben":["Ħajt tat-trinka juri xquq u qed jitfarrak. X'inhu sewwa?","Inti taħdem eżatt ħdejn il-foss.","Waqqaf ix-xogħol u agħmel li dawk responsabbli jassiguraw il-ħofra tat-tħaffir.","Sempliċement issuq eqreb lejn it-tarf biex tagħlaq il-foss.","Approfondixxi t-trinka aktar mingħajr protezzjoni.","Xquq u movimenti tal-art jistgħu jindikaw instabbiltà u jeħtieġu aktar valutazzjoni tas-sikurezza."],"b-betanken":["X'tagħti attenzjoni meta tagħti l-fjuwil ta' magna tal-art?","It-tank huwa kważi vojt.","Sikura l-magna u s-sorsi tat-tqabbid skond l-istruzzjonijiet tal-manifattur u evita tixrid.","Dejjem imla mill-ġdid petrol jew diesel fil-kabina.","Duħħan waqt il-forniment tal-fjuwil meta ma jkunx hemm riħ.","Il-perikli tan-nar u ambjentali meta jiġi mmaniġġjat il-fjuwil jeħtieġu miżuri protettivi xierqa."],"b-laufwerk":["Għaliex il-binarji u l-undercarriage jeħtieġ li jiġu ċċekkjati regolarment?","Tinnota vibrazzjonijiet mhux tas-soltu waqt is-sewqan.","Sabiex il-magna tkun tista 'timxi aktar malajr.","Minħabba li l-ħsara tista 'taffettwa gwida u stabbiltà siguri.","Għax ix-xogħol huwa dejjem permess mingħajr spezzjoni viżwali.","Ħsara lis-sewqan tista 'taffettwa l-manuvrabbiltà, l-istabbiltà u l-operat sikur."],"b-einweisen":["X'inhu meħtieġ meta taħdem ħdejn it-traffiku pubbliku pedonali?","Skavatur jaħdem direttament fuq it-tarf ta 'bankina.","Il-persuni mexjin għandhom jimxu miż-żona tal-iswing huma stess.","Sempliċement waħħal sinjal fuq il-pala.","Iċċekken b'mod effettiv iż-żona ta 'periklu u dderieġi t-traffiku b'mod sikur.","Partijiet terzi m'għandhomx jidħlu fiż-żona ta 'periklu ta' magni tal-moviment tal-art; Huma meħtieġa barrieri xierqa u rotot tat-traffiku."],"g2-fahrweg":["Hemm likwidu mxerred fit-triq 'il quddiem. Kif tmur dwar dan?","Il-forklift se jsuq direttament fuq iż-żona tiżloq.","Waqqaf is-sewqan u żomm il-post ta' periklu assigurat jew imneħħi.","Issuq fuq il-post kemm jista 'jkun malajr bil-furketta mgħollija.","Tama għal tajers aktar niexfa u kompli ssuq mhux mibdula.","Ir-rotot ikkontaminati jipperikolaw l-istabbiltà u għandhom ikunu assigurati b'mod adegwat qabel issuq fuqhom."],"g2-sichtladung":["Pallet għoli jimblokka l-veduta 'l quddiem. X'inhu sewwa?","Trid issuq lejn żona tal-ħażna u ma tistax tara r-rotta.","Erfa' l-pallet 'l fuq sakemm tkun tista' tara taħtha.","Issuq biss billi tuża metodi xierqa u sikuri, bħar-rivers b'dehra ċara.","Inti xorta tista 'ssuq fit-triq mingħajr sinjal jew veduta ċara.","Id-direzzjoni tal-ivvjaġġar u l-viżibilità għandhom jippermettu osservazzjoni sigura tar-rotta tat-traffiku; It-tagħbijiet m'għandhomx jissostitwixxu l-ispezzjoni viżwali."],"g2-fussgaengerstop":["Pedestrian jieqaf eżatt ħdejn il-forklift. X'qed tagħmel?","Il-persuna tinsab fil-medda possibbli tas-sewqan u tal-pern.","Aqbeż il-pedestrian billi taċċellera fil-qosor.","Issuq ħdejn il-persuna bit-tagħbija mgħollija.","Waqqaf u kompli biss issuq f'distanza sigura.","In-nies għandhom jibqgħu barra miż-żona ta' periklu; Jekk meħtieġ, il-vjaġġ għandu jiġi interrott."],"g2-hubmast":["Tinnota linja idrawlika bil-ħsara fuq l-arblu tal-lift. X'japplika?","Iż-żejt idrawliku qed inixxi b'mod viżibbli mill-implimentazzjoni.","Ħu l-forklift mit-tħaddim u rrapporta l-ħsara.","Iċċekkja t-tnixxija bl-idejn waqt l-irfigħ.","Neħħi biss tagħbijiet iżgħar sakemm jintemm ix-shift.","Il-ħsara idrawlika tista 'twassal għal movimenti mhux ikkontrollati; użu sikur mhux garantit sakemm it-test."],"g2-lagerregal":["Trid taħżen pallet fuq xkaffa. X'tiċċekkja l-ewwel?","Il-livell tal-ixkaffa huwa għoli u l-kapaċità tat-tagħbija għandha tinżamm.","Imbotta l-pallet fuq l-ixkaffa malajr kemm jista 'jkun.","Iċċekkja l-kompartiment tal-ixkaffa, il-piż tat-tagħbija u l-ispazju għall-ħażna ħieles għall-adegwatezza.","Stima l-piż totali bbażata biss fuq in-numru ta 'kaxxi.","L-ixkafef u t-tagħmir li jġorr it-tagħbija għandhom jaqblu mas-sitwazzjoni tat-tagħbija u l-ħażna."],"g2-batterieschaden":["Batterija tal-forklift hija bil-ħsara esternament. X'inhu sewwa?","Qabel it-tagħbija, jiġu nnutati xquq jew fluwidu mhux tas-soltu.","Għatti l-ħsara b'tejp li jwaħħal u tagħbija immedjatament.","Ħalli persuna oħra tiċċarġja l-batterija mingħajr ma tiċċekkjaha.","Tiċċarġjax jew tużax u tinforma lill-ispeċjalisti responsabbli.","Batteriji bil-ħsara joħolqu perikli elettriċi u kimiċi u jeħtieġu valutazzjoni professjonali."],"g2-fahrerkabine":["X'japplika għal oġġetti maħlula fiż-żona tas-sewwieq?","L-għodda huma fuq l-art ħdejn il-pedali tal-kontroll.","Neħħi l-oġġetti u żomm iż-żona operattiva ċara.","Żomm l-għodda biss b'sieq waħda waqt is-sewqan.","Aħbi partijiet sfużi taħt is-sedil tas-sewwieq.","Oġġetti sfużi jistgħu jimblokkaw il-pedali u jfixklu l-operat sikur tal-vettura."],"g2-uebergabe":["Inti tieħu f'idejha forklift wara bidla tax-xift. Dak x'jinkludi?","Kollega uża l-vettura l-aħħar.","Assumi li l-kollega ħa f'idejh il-kontrolli kollha.","Wettaq l-ispezzjoni meħtieġa u staqsa dwar difetti magħrufa.","Ibda l-vjaġġ mingħajr ma tħares lejn il-magna.","Il-persuna li tieħu f'idejha għandha tiżgura li tkun f'kundizzjoni sigura qabel l-użu."],"g2-transportsicherung":["Oġġett għoli huwa maħlul fuq il-pallet. Kif taġixxi?","It-tagħbija tista' tinqaleb 'il quddiem meta tkun qed tibbrejkja.","Ġorru l-furketta partikolarment għolja sabiex it-tagħbija tibqa 'stabbli.","Ħu l-kurvi bil-mod, mur dritta aktar malajr.","Waħħal it-tagħbija b'mod stabbli u waħħalha kontra t-twaqqigħ jew il-waqgħa.","Tagħbijiet maħlula għandhom jiġu stabbilizzati qabel it-trasport sabiex il-movimenti tal-ibbrejkjar u tas-sewqan ma jikkawżawhomx jaqgħu."],"g2-arbeitsende":["X'inhu importanti b'forklift waħdu?","Int tispiċċa x-xift tiegħek u tħalli ż-żona.","Ipparkja l-vettura b'mod sigur u waħħalha kontra t-tidwir u l-użu mhux awtorizzat.","Ħalli ċ-ċavetta ġewwa sabiex il-kollegi jkunu jistgħu jsibu l-magna.","Ħalli l-furketta fil-livell tal-għajnejn sabiex tkun viżibbli.","L-ipparkjar sikur jinkludi l-immaniġġjar tat-tagħbija mnaqqsa u l-protezzjoni kontra l-moviment u l-ikkummissjonar mhux awtorizzat."],"g2-bremsweg":["Għaliex għandek tagħti attenzjoni partikolari lid-distanza tal-ibbrejkjar taħt tagħbija?","Il-forklift jittrasporta merkanzija tqila minn korsija tal-maħżen.","Dejjem ibbrejkja aktar tard b'tagħbija tqila milli mingħajr tagħbija.","Aġġusta l-veloċità għall-viżibilità, l-art u l-kundizzjonijiet tat-tagħbija.","Waqt l-ibbrejkjar, għolli t-tagħbija f'daqqa biex tnaqqas aħjar.","Il-massa u l-kundizzjoni tat-triq jinfluwenzaw id-distanza tal-waqfien; veloċità adattata hija essenzjali."],"g2-rampe":["X'tiċċekkja qabel ma titla' rampa wieqaf?","Ir-rotta tista' tkun wieqaf wisq għall-vettura.","Issuq fuq ir-rampa b'veloċità massima irrispettivament mill-gradjent.","Issuq fuq it-tarf tar-rampa bit-tagħbija mgħollija.","Iċċekkja l-gradjent permissibbli u l-mod ta 'tħaddim sikur mill-ispeċifikazzjonijiet tal-vettura.","Jistgħu jintużaw biss rampi fil-limiti operattivi maħsuba; L-istruzzjonijiet tat-tħaddim u l-kontroll tat-tagħbija huma deċiżivi."],"g2-zinke":["Pallet huwa usa 'mill-distanza tal-furketta. X'għandu jittieħed kont?","Inti tippjana li tieħu tagħbija mhux tas-soltu kbira.","Aġġusta d-distanza tal-furketta u l-punti tal-immuntar biex ikunu adattati għat-tagħbija.","Uża tinda waħda biss jekk it-tagħbija tkun wiesgħa wisq.","Għolli t-tagħbija f'angolu sakemm tilħaq il-pożizzjoni korretta.","L-assorbiment tat-tagħbija uniformi u adattat inaqqas iż-żliq u t-twaddib."],"g2-betriebsanweisung":["X'rwol għandu r-regolamentazzjoni operattiva tat-traffiku?","Żoni immarkati one-way u pedonali japplikaw fil-maħżen.","Bil-forklifts, japplikaw biss ir-regoli tat-triq pubblika.","Segwi r-rotot speċifikati u r-regoli tat-traffiku.","Injora l-marki ladarba l-vettura tkun mgħobbija.","Ir-rotot tal-kumpanija u r-regoli tas-sigurtà jipproteġu t-traffiku tal-forklifts u n-nies bil-mixi."],"g2-nothalt":["L-istering jirreaġixxi b'mod mhux tas-soltu waqt is-sewqan. X'inhu sewwa?","Il-vettura ma tistax tiġi kkontrollata aktar bħas-soltu.","Issuq b'veloċitajiet ogħla biex tagħmel l-istering aktar reattiv.","Ikkumpensa għall-iżball b'diflessjonijiet tal-istering partikolarment kbar.","Waqqaf f'post sigur u ċċekkja l-vettura.","Steering indebolit jipperikola gwida sigura; il-magna m'għandhiex tkompli titħaddem mingħajr kontroll."],"g2-anschlagkette":["Trid tmexxi tagħbija mdendla liberament b'forklift. X'japplika?","Tagħbija għandha tistrieħ fuq ganċ taħt il-frieket.","Biss b'apparat approvat u tagħmir adattat li jġorr it-tagħbija.","Kwalunkwe katina se tagħmel jekk it-tagħbija ma tkunx tqila.","Ikklampja l-katina direttament bejn iż-żewġ frieket.","It-tagħbijiet imdendlin liberament jibdlu l-istabbiltà; Approvazzjonijiet tal-manifattur u faċilitajiet xierqa huma meħtieġa."],"g2-rollenlast":["Komponent ċilindriku jinsab mhux assigurat fuq pallet. X'qed tagħmel?","It-tagħbija tista' tirrombla waqt it-trasport.","Avviċina l-pallet partikolarment jerkily.","Żgura l-komponent kontra l-irrumblar qabel ma jinġabar il-pallet.","Pożizzjona t-tines għoli biżżejjed li l-komponent ma jkunx viżibbli.","Tagħbijiet tondi jew rolling jeħtieġu protezzjoni affidabbli kontra bidliet fil-pożizzjoni."],"g2-pruefplakette":["Kif tkun taf jekk il-forklift jistax jintuża?","Hemm stiker ta 'spezzjoni mwaħħla mal-magna.","Kwalunkwe stiker dejjem tissostitwixxi l-ispezzjoni viżwali ta 'kuljum.","Nuqqas ta' spazju ħieles jista' jiġi sostitwit b'sewqan bir-reqqa.","Minbarra l-iċċekkjar tal-vettura, għandhom jitqiesu l-istatus validu tat-test u l-approvazzjoni operattiva.","L-ittestjar rikorrenti u l-kontrolli operattivi ta 'kuljum jissodisfaw funzjonijiet ta' sikurezza differenti."],"g2-licht":["Id-dawl fil-maħżen intefa f'daqqa. X'inhu sewwa?","Ma tistax tara l-ostakli fit-triq b'mod sigur.","Waqqaf is-sewqan sakemm tkun garantita viżibilità sigura.","Żid il-veloċità tas-sewqan biex tħalli ż-żona mudlama.","Kompli sewqan bil-frieket mgħollija mingħajr spezzjoni viżwali.","Rotta li ma tistax tiġi injorata b'mod sikur m'għandhiex tiġi misjuqa mingħajr miżuri ta' sikurezza effettivi."],"g2-ueberhang":["Tagħbija testendi ferm lil hinn mill-ġenb tal-furketta. X'qed tiċċekkja?","Trid tittrasporta l-pallet minn xatba dejqa.","Ikkumpensa għall-projezzjoni laterali b'kurva mgħaġġla.","Evalwa l-ispazju ħieles, l-istabbiltà u l-kapaċità tat-tagħbija permissibbli qabel issuq.","Issuq it-tagħbija b'veloċità massima irrispettivament mill-forma tagħha.","Sporġenza jżid ir-riskji ta 'ħabta u jistgħu jibdlu l-istabbiltà u l-ispazju tat-traffiku meħtieġ."],"g2-wartungsbereich":["Hemm barrieri quddiem żona ta 'manutenzjoni. Kif qed iġġib ruħek?","Ir-rotta tas-soltu tiegħek hija temporanjament magħluqa.","Ċaqlaq l-ostakli fil-qosor u ssuq mingħajr ma jiġi osservat.","Issuq direttament fiż-żona tax-xogħol taħt tagħbija.","Osserva l-għeluq u agħżel rotta alternattiva approvata.","Żoni magħluqa ma jistgħux jidħlu jew jinstaqu mingħajr permess."],"g2-bremsprobe":["Meta jagħmel sens test funzjonali tal-brejk tas-servizz?","Inti tipprepara l-forklift qabel ix-xogħol.","Bħala parti mill-ispezzjoni meħtieġa qabel l-użu.","Wettaq biss wara inċident serju.","Biss jekk it-trakk ikun diġà laħaq veloċità għolja.","Il-funzjonalità tal-faċilitajiet rilevanti għas-sikurezza hija kkontrollata qabel l-użu."],"g2-fahrzeuganhaenger":["Trid tiġbed karru b'forklift. X'inhu meħtieġ?","Il-kumpanija qed tippjana trasport b'tagħbija mwaħħla.","Orbot kull karru ma' furketta mingħajr ma tiċċekkja.","Osserva l-approvazzjoni tal-manifattur, l-akkoppjar adattat u t-tagħbija tat-tensjoni permissibbli.","Żid il-pressjoni tat-tajer u ssuq off.","It-tħaddim tal-ferrovija huwa possibbli biss b'mod sigur fi ħdan l-ispeċifikazzjonijiet tekniċi u b'konnessjoni xierqa."],"g2-rueckfahrt":["X'inhu importanti meta tirriversja bil-forklift?","Hemm żona konfuża fil-korsija tal-maħżen.","Dejjem ħares biss fil-mera ta 'wara, irrispettivament mill-inħawi.","Issuq mingħajr viżibilità sakemm il-ħorn ikun ġie ppressat darba.","Osserva b'mod sikur ir-rotta u ż-żona tan-nies u, jekk meħtieġ, agħtihom struzzjonijiet.","It-treġġigħ lura jeħtieġ ħarsa ċara jew miżuri ta' sikurezza addizzjonali effettivi."],"g2-lastentnahme":["Inti tieħu pallet minn fuq xkaffa għolja. X'inhu sewwa?","Il-paletta tista' ma tkunx iċċentrata.","Aqbad it-tagħbija b'mod sikur u stabbilizzaha qabel tbaxxi.","Ħalli l-pallet jitbandal lejn il-ġenb hekk kif iġbedha 'l barra.","Iċċekkja taħt il-pallet mgħolli biex tara jekk huwiex bil-ħsara.","L-irfigħ u t-tnaqqis ikkontrollati jipprevjenu tagħbijiet milli jaqgħu u movimenti perikolużi."],"h2-absenkweg":["Għaliex iż-żona taħt pjattaforma tax-xogħol mill-ajru trid tibqa' ċara?","Il-basket jitbaxxa u l-materjali jitqiegħdu taħtu.","Agħfas materjali 'l isfel bil-basket.","Żomm għajnejk biss fuq iż-żona tas-sieq tal-operatur.","Evita r-riskju ta 'tgħaffiġ u ħabta meta tbaxxi.","Iż-żona ta' tbaxxija m'għandux ikun fiha nies jew ostakli li jistgħu jinqabdu."],"h2-transporthoehe":["Kif timxi palk mobbli fuq passaġġ baxx?","It-tneħħija hija aktar baxxa mill-boom estiż.","Poġġi l-pjattaforma f'pożizzjoni ta 'trasport xierqa skond l-istruzzjonijiet tat-tħaddim.","Ħalli l-boom estiż u jimxu tul taħt is-saqaf.","Agħfas il-basket mal-ġenb tal-qafas tal-bieb.","Għall-movimenti tal-ivvjaġġar, l-għoli ġenerali u l-pożizzjoni tat-trasport għandhom jaqblu mal-ispeċifikazzjonijiet tal-manifattur u l-passaġġ."],"h2-bodenoeffnung":["Hemm fetħa mhux assigurata fl-art ħdejn il-palk. Kif tirreaġixxi?","Punt tas-sewqan jew ta 'appoġġ jinsab ħdejn il-ftuħ.","Poġġi appoġġ direttament fuq it-tarf tal-ftuħ.","Ibdel il-post ta 'installazzjoni jew ikkontrolla l-kapaċità tat-tagħbija u l-iżgurar professjonalment.","Għatti biss il-punt tal-periklu b'kaxxa tal-kartun.","Il-fetħiet u ż-żoni tat-tarf jistgħu jfallu taħt tagħbijiet ta 'appoġġ u għandhom jitqiesu b'mod effettiv."],"h2-rettungsperson":["Għaliex it-tieni persuna trid tkun familjari mal-proċedura ta' salvataġġ?","Operatur jista' jsir inkapaċitat fil-quċċata.","Allura dak ix-xogħol fil-basket ġeneralment jista 'jseħħ mingħajr sigurtà.","Sabiex l-istadju jkun jista 'jitħaddem aktar malajr milli permess.","Sabiex salvataġġ sikur jista 'jinbeda f'emerġenza.","Kunċett ta' salvataġġ għandu jqis l-assistenza fuq l-art f'każ ta' falliment jew emerġenza."],"h2-werkzeugabwurf":["X'japplika għal għodod f'altitudni għolja?","Għodda maħlula tista 'taqa' fuq it-tarf tal-basket.","Għodod siguri sabiex ma jipperikolaw lil ħadd jew jaqgħu għal isfel.","Sempliċement poġġi l-għodda fuq il-puġġaman biex tnaqqas it-tagħbija.","Jekk meħtieġ, armi l-għodda 'l isfel mill-basket.","Oġġetti li jaqgħu taħt il-periklu jipperikolaw lin-nies; Il-materjal għandu jinħażen b'mod sigur."],"h2-trittstufe":["Kaxxa għandha sservi bħala spazju wieqfa addizzjonali fil-basket. X'inhu sewwa?","Inkella bilkemm tilħaq il-post tax-xogħol.","Poġġi l-kaxxa fuq il-puġġaman u titla’ fuqha.","Titlax fuq elevazzjonijiet improvizzati; Uża tagħmir tax-xogħol xieraq.","Intenzjonalment tagħbija l-basket lil hinn mill-għoli permess.","Elevazzjonijiet improvizzati jfixklu l-protezzjoni maħsuba għall-waqgħa u mhumiex permessi."],"h2-lastverteilen":["X'tagħti kas meta jkun hemm diversi nies fil-basket tax-xogħol?","Żewġ persuni qed jaħdmu fil-basket b'għodda tqal.","Iġġudika t-tagħbija bbażata biss fuq id-daqs tal-għodda.","Aħżen għodod tqal direttament fuq il-puġġaman protettiv.","Taqbiżx it-tagħbija permissibbli tal-basket inklużi n-nies u l-għodda.","Il-kapaċità tat-tagħbija permessa tinkludi n-nies, il-materjali u l-għodda kollha fil-basket."],"h2-abstuetzplatte":["Meta jitqiesu shims addizzjonali għall-appoġġi?","L-art ta 'l-installazzjoni tista' ġġorr biss tagħbija limitata.","Jekk dan huwa meħtieġ għal distribuzzjoni sigura tat-tagħbija skond l-ispeċifikazzjonijiet.","Sabiex tpoġġi l-appoġġi kemm jista 'jkun qrib it-tarf ta' fossa tal-kostruzzjoni.","Sabiex tuża kwalunkwe medda itwal mingħajr informazzjoni tal-manifattur.","Żoni ta' kuntatt suffiċjenti huma meħtieġa għal forzi ta' appoġġ sikuri."],"h2-baugrube":["Stadju għandu jkun jinsab direttament fit-tarf ta 'fossa tal-kostruzzjoni. X'qed tiċċekkja?","Il-ħamrija ta’ taħt tista’ ċedi lateralment minħabba l-ħofra tat-tħaffir.","Estendi l-appoġġi fil-fossa tat-tħaffir.","Żgura biżżejjed distanza ta 'sikurezza u kapaċità ta' ġarr ta 'tagħbija ta' taħt il-wiċċ.","Ikkumpensa biss għar-riskju billi tneħħi l-basket bil-mod.","Il-fosos tat-tħaffir jistgħu jaffettwaw l-istabbiltà minħabba l-inklinazzjoni u l-falliment ta 'taħt il-ħamrija."],"h2-witterung":["Is-silġ jidħol waqt l-użu. Kif taġixxi?","L-uċuħ tal-kontroll u ż-żona tax-xogħol isiru lixxi.","Għolli l-istadju biex tevita borra u silġ.","Injora t-twissijiet sakemm il-pjattaforma tkun mixgħula.","Interrrompi x-xogħol u tivvaluta mill-ġdid il-kundizzjonijiet tat-tħaddim skont l-istruzzjonijiet tat-tħaddim.","Bidliet fit-temp jistgħu jbiddlu r-responsabbiltà, l-operabbiltà u l-limiti sikuri tal-użu."],"h2-aufbaukontakt":["Kostruzzjoni tal-azzar tillimita l-passaġġ tal-basket. X'inhu importanti?","Waqt l-irfigħ hemm riskju ta 'tgħaffiġ bejn il-basket u t-trasportatur.","Ippjana l-movimenti sabiex ġismek u l-basket ma jinqabdux.","Agħmel il-vjaġġ aktar mgħaġġel sabiex il-basket jgħaddi aktar malajr.","Imbotta l-kostruzzjoni bil-basket lejn il-ġenb.","Il-punti ta' niskata bejn il-pjattaforma u l-ambjent jeħtieġu osservazzjoni bir-reqqa u moviment ikkontrollat."],"h2-sicherheitsabstand":["Meta l-erja ta’ periklu ta’ stadju trid tiġi maqtugħa?","Taħt is-sit tgħaddi rotta tat-trasport pubbliku.","Biss jekk oġġett ikun diġà waqa '.","Jekk partijiet terzi jistgħu jkunu fil-periklu minħabba moviment jew oġġetti li jaqgħu.","Qatt, peress li l-basket tax-xogħol bażikament jipprevjeni l-perikli kollha.","Iż-żona taħt u ħdejn l-istadju għandha tkun protetta kontra perikli prevedibbli."],"h2-korbtor":["X'japplika għall-bieb tad-dħul tal-basket tax-xogħol?","Int diġà fl-għoli tax-xogħol.","Ħalli l-bieb miftuħ sabiex tkun tista' toħroġ aktar malajr.","Orbot il-bieb miftuħ b'mod permanenti b'ħabel.","Żomm il-bieb magħluq skond il-mekkaniżmu ta 'qfil ipprovdut.","Is-serraturi pprovduti huma parti mill-miżuri protettivi kontra l-waqgħa mill-gaġġa tax-xogħol."],"h2-energieleitung":["X'japplika jekk linja overhead ma tintefax b'mod sikur?","Inti taħdem mal-pjattaforma tax-xogħol mill-ajru ħdejhom.","Tiżgura distanzi ta' sikurezza speċifikati u miżuri protettivi meħtieġa.","Mexxi l-basket eżatt quddiem il-linja sakemm ma jintmessx.","Afda fit-tajers tal-plastik u aħdem mingħajr ebda vojt.","Flashovers elettriċi huma wkoll possibbli mingħajr kuntatt dirett; Id-distanzi tas-sigurtà huma meħtieġa."],"h2-schwanken":["Il-basket tax-xogħol jibda jixxengel b'mod mhux tas-soltu. X'inhu sewwa?","Il-moviment m'għadux ikkontrollat.","Aġġusta mill-ġdid bla kontroll b'kontromovimenti rapidi.","Waqqaf il-moviment u ċċekkja l-kawża jew il-kundizzjonijiet tat-tħaddim.","Żid nies żejda mal-basket biex tagħmilha itqal.","Vibrazzjoni mhux tas-soltu tista 'tindika kundizzjonijiet ta' tħaddim mhux xierqa jew malfunzjoni."],"h2-ladegeraet":["Kejbil tal-iċċarġjar għall-istadju mħaddem bl-elettriku huwa bil-ħsara. X'qed tagħmel?","Meta tikkonnettja, insulazzjoni bil-ħsara hija viżibbli.","Mess il-ħsara b'ingwanti mxarrbin.","Agħfas il-plagg fis-sokit kemm jista 'jkun.","Tibdiex il-proċess tal-iċċarġjar u ċċekkja l-kejbil professjonalment.","Wiring elettriku bil-ħsara joħloq riskju ta 'xokk elettriku u nar."],"h2-gelaenderanbau":["Tista 'tneħħi puġġaman lilek innifsek biex tersaq eqreb?","Komponent jipprevjeni lin-nies milli jersqu lejn is-sit tax-xogħol.","M'għandekx timmodifika jew tneħħi tagħmir protettiv waħdek.","Wara l-irfigħ, ħoll il-puġġaman u installaha aktar tard.","Kompli aħdem mingħajr railing sakemm xi ħadd ikun wieqaf ħdejha.","L-apparati protettivi strutturali ma jistgħux jinbidlu mingħajr speċifikazzjonijiet permissibbli u miżuri ta 'sostituzzjoni bla periklu."],"h2-lastkran":["Tista' tintuża l-pjattaforma bħala krejn biex tgħolli tagħbija?","Il-materjal għandu jiġi ttrasportat mdendel liberament ħdejn il-basket tax-xogħol.","Kull meta l-piż ikun inqas mill-piż tal-ġisem tiegħek stess.","Biss jekk il-manifattur u t-tagħmir jippermettu espressament dan l-użu speċjali.","Sempliċement waħħal ganċ mal-puġġaman u lift materjal.","Pjattaformi tax-xogħol mill-ajru mhumiex iddisinjati awtomatikament għal xogħol ta 'krejn jew tagħbijiet sospiżi addizzjonali."],"h2-arbeitsvorbereitung":["X'jiġri fit-tħejjija għal post ġdid?","S'issa ma tafx is-sit tal-kostruzzjoni.","Stima biss id-distanza għall-eqreb lott tal-parkeġġ.","Irrispettivament mill-inħawi, estendiha kompletament immedjatament.","Evalwa l-perikli, il-ħamrija, ir-rotot tat-traffiku, is-salvataġġ u l-adegwatezza tat-tagħmir.","Valutazzjoni tar-riskju relatata mal-post hija prerekwiżit għal kundizzjonijiet operattivi sikuri."],"h2-kabelschlaufe":["Kejbil tad-dawl jinsab madwar il-passaġġ tal-istadju. X'inhu sewwa?","Il-kejbil jista 'jinqabad waqt il-moviment.","Ċar it-triq u jipproteġi l-kejbils elettriċi mill-ħsara.","Uża l-kejbil bir-roti bħala limitu tat-triq.","Għolli l-basket mingħajr ma tiċċekkja l-erja tal-art.","Kejbils li jinqalgħu jew imfarrak jistgħu jikkawżaw perikli elettriċi u mekkaniċi."],"h2-leitungsnaehe":["Min jiċċara l-miżuri protettivi fuq sistema elettrika?","Il-pjattaforma għandha taħdem qrib tagħmir ħaj.","Il-persuna fil-basket tiddeċiedi biss bl-għajnejn.","Involvi awtoritajiet responsabbli u timplimenta miżuri protettivi kkoordinati.","Id-distanza tiġi determinata biss wara li jkun beda x-xogħol.","Ix-xogħol qrib is-sistemi elettriċi jeħtieġ miżuri protettivi ppjanati u kkoordinati."],"h2-funkkommunikation":["Għaliex is-sinjali bejn l-art u l-basket għandhom ikunu ċari?","Persuna fl-art tassisti fil-manuvra.","Sabiex diversi nies ikunu jistgħu jagħtu struzzjonijiet kontradittorji fl-istess ħin.","Sabiex it-tnaqqis ta 'emerġenza jista' jiġi ppruvat mingħajr struzzjonijiet.","Sabiex il-movimenti jsiru biss wara komunikazzjoni ċara.","Komunikazzjoni ċara tnaqqas il-movimenti mhux korretti u l-ħabtiet meta timmanuvra."],"h2-neuebedienung":["Inti taqleb għal tip differenti ta 'stadju. X'inhu meħtieġ?","Il-funzjonijiet operattivi jvarjaw b'mod sinifikanti.","Istruzzjoni speċifika għall-apparat qabel l-użu indipendenti.","Just taqra l-logo tal-kumpanija fuq l-apparat.","Test drive bil-basket diġà estiż mingħajr struzzjonijiet.","Il-kwalifika waħedha ma tissostitwixxix l-istruzzjoni fit-tip ta' apparat speċifiku."],"h2-steckanschluss":["X'għandek tiċċekkja qabel ma tikkonnettja ċarġer?","Jeħtieġ li tiġi ċċarġjata pjattaforma elettrika tax-xogħol mill-ajru.","Uża kwalunkwe sokit irrispettivament mill-kundizzjoni u l-fjus.","Iċċekkja l-konnessjoni xierqa u l-kejbil bla ħsara skont l-istruzzjonijiet tal-manifattur.","Aqla 'l-plagg tal-enerġija regolarment waqt l-iċċarġjar.","Konnessjonijiet elettriċi xierqa u intatti jipproteġu kontra xokk elettriku u nar."],"h2-absperrpersonal":["Persuna tidħol fiż-żona magħluqa waqt xogħol ta' rfigħ. X'qed tagħmel?","Tista 'tara persuna direttament taħt il-basket tax-xogħol.","Kompli sewqan jekk il-persuna tkun liebsa elmu protettiv.","Waqqa 'għodda fid-direzzjoni tagħhom bħala sinjal ta' twissija.","Waqqaf il-moviment perikoluż u qabbad iż-żona.","Ostaklu ma jissostitwixxix l-osservazzjoni taż-żona ta' periklu waqt it-tħaddim."],"k2-arbeitsplanung":["X'għandu jiġi inkluż fil-preparazzjoni tax-xogħol qabel operazzjoni tal-krejn?","It-tagħbija, il-post u r-rotta tat-trasport għadhom ma ġewx ikkoordinati.","Neħħi l-itqal tagħbija l-ewwel mingħajr aktar ippjanar.","Immarka biss l-iqsar rotta fl-art tas-sala.","Iċċara bil-quddiem il-kapaċità tat-tagħbija, bragi, mogħdija tat-tagħbija u żona ta 'periklu.","Moviment ippjanat tal-krejn jeħtieġ immaniġġjar xieraq tat-tagħbija, rotot sikuri u miżuri protettivi kkoordinati."],"k2-hakenposition":["Kif jitqiegħed il-ganċ tal-krejn fuq it-tagħbija qabel l-irfigħ?","Il-punti tat-twaħħil huma taħt il-krejn.","L-aktar vertikalment possibbli 'l fuq miċ-ċentru tal-gravità skond il-waqfien.","Offset 'l bogħod lejn il-ġenb sabiex it-tagħbija titbandal aktar malajr.","Fi kwalunkwe każ fit-tarf ta 'barra tat-tagħbija, irrispettivament miċ-ċentru tal-gravità.","L-applikazzjoni vertikali tal-forza u l-punti ta 'ankra adattati jnaqqsu l-moviment tal-ġenb u l-movimenti mhux ikkontrollati."],"k2-hakengabel":["Ganċ tat-tagħbija juri deformazzjoni notevoli. X'japplika?","Il-ganċ jidher mgħawweġ mill-istat tas-soltu tiegħu.","Liwja d-deformazzjoni lura bit-tagħbija li jmiss.","Waqqaf it-tħaddim tal-krejn u ċċekkja l-ganċ minn espert.","Waħħal biss tagħbijiet ħfief u kompli jaħdem.","Id-deformazzjoni tista 'taffettwa s-sigurtà tal-ganċ; użu ulterjuri mhux awtorizzat mhux permess."],"k2-zugueberlast":["Il-piż huwa itqal milli inizjalment preżunt. X'qed tagħmel?","Informazzjoni ġdida dwar il-piż tqum waqt il-preparazzjoni.","Ibdel ir-riżerva tas-sigurtà b'irfigħ aktar mgħaġġel.","Injora l-piż tat-tagħbija billi twaħħalha ma 'punt ieħor.","Iddetermina t-tagħbija attwali u ċċekkja mill-ġdid il-limiti tat-tagħbija.","L-irfigħ sikur jeħtieġ dejta affidabbli dwar it-tagħbija u konformità mal-kapaċitajiet rilevanti kollha tat-tagħbija."],"k2-arbeitskorb":["Ganċ tal-krejn ordinarju jista 'jġorr in-nies faċilment?","Persuna trid tasal f'post għoli tax-xogħol.","Le, it-trasport tal-passiġġieri jeħtieġ faċilitajiet u miżuri speċjali permessi.","Iva, jekk il-persuna żżomm mal-ħabel tal-braga.","Iva, hekk kif il-puplesija titwettaq partikolarment bil-mod.","It-trasport tan-nies huwa permess biss taħt kundizzjonijiet speċjali pprovduti għal dan il-għan."],"k2-bruecke":["Krejn tal-pont jimxi tul mogħdija tas-sala kondiviża. X'inhu importanti?","L-impjegati jibqgħu taħt ir-rotta tat-trasport.","Issuq bit-tagħbija eżatt fuq l-irjus tal-impjegati.","Żomm b'mod effettiv ir-rotta tat-tagħbija u ż-żona tat-traffiku ċari u siguri.","Uża biss il-ħorn tat-twissija minflok miżuri ulterjuri.","Nies f'riskju m'għandhomx ikunu taħt tagħbijiet sospiżi jew fil-mogħdija tat-trasport tagħhom."],"k2-zweitekrane":["Żewġ krejnijiet jaħdmu f'żona li tikkoinċidi. X'inhu meħtieġ?","Booms jew tagħbijiet jistgħu jaħbtu ma' xulxin.","Iż-żewġ operaturi tal-krejn jaħdmu fl-istess ħin mingħajr ftehim minn qabel.","Il-movimenti huma deliberatament aċċellerati biex jiġu evitati intersezzjonijiet.","Tikkoordina l-operazzjonijiet u tieħu miżuri xierqa biex tevita theddid reċiproku.","Żoni tax-xogħol li jikkoinċidu jeħtieġu organizzazzjoni operazzjonali kkoordinata u salvagwardji xierqa."],"k2-pruefbuch":["X'inhu s-sinifikat tal-ispezzjoni obbligatorja tal-krejn rikorrenti?","Il-magna tintuża regolarment fl-operazzjonijiet.","Jissupplimenta l-kontroll operattiv bl-eżami espert preskritt.","Jissostitwixxi b'mod permanenti kwalunkwe spezzjoni viżwali qabel ma jibda x-xogħol.","Huwa meħtieġ biss wara ħabta.","Spezzjonijiet rikorrenti u kontrolli operattivi kontinwi għandhom kompiti differenti."],"k2-absetzflaeche":["Iż-żona tat-tqegħid maħsuba hija irregolari. Kif taġixxi?","It-tagħbija tista' tinqaleb meta titqiegħed.","Poġġi t-tagħbija fuq kantuniera waħda u ħalliha tistrieħ mhux mibdula.","Ipprepara bażijiet jew uċuħ adattati, li jifilħu t-tagħbija u stabbli.","Poġġi persuna waħda taħt it-tagħbija waqt li tbaxxi.","Iż-żoni ta' tqegħid għandhom isostnu t-tagħbija b'mod sikur u jipprevjenu movimenti perikolużi ta' twarrib jew rolling."],"k2-anfahrbereich":["Qabel ma l-krejn jibda jiċċaqlaq, hemm persuna waħda fiż-żona tal-ivvjaġġar. X'qed tagħmel?","Ir-rotta hija mblukkata minn persuna.","Imbotta l-persuna fil-ġenb b'test drive qasir.","Iċċaqlaq billi tuża l-iswiċċ tal-limitu waħdu mingħajr spezzjoni viżwali.","Ibda l-moviment biss meta ż-żona ta 'periklu tkun ċara u sigura.","Il-movimenti tas-sewqan u tal-pern m'għandhomx jipperikolaw lin-nies."],"k2-schlaffseil":["Għaliex il-ħabel tal-parank m'għandux isir laxk b'mod inkontrollabbli meta jitqiegħed?","It-tagħbija hija mixgħula, il-ganċ jitbaxxa aktar.","Sabiex il-ħabel u l-ganċijiet ma jiġux iġġammjati jew soġġetti għal tagħbija mhux ikkontrollata.","Sabiex it-tagħbija tista 'mbagħad tinġibed lateralment mill-ħabel.","Sabiex il-bragi jinqalgħu mill-ganċ.","Rotot tal-kejbil mhux ikkontrollat ​​jista 'jwassal għal taħbil u movimenti perikolużi tat-tagħbija."],"k2-pendel":["Tagħbija li tkun qed tiġi ttrasportata tibda titbandal. X'inhu sewwa?","It-tagħbija timxi lateralment aktar milli ppjanat.","Ikkumpensa b'kontromovimenti rapidi u b'veloċità sħiħa.","Naqqas il-movimenti b'mod ikkontrollat ​​u vjaġġar kalm mingħajr nies fiż-żona ta 'periklu.","Żomm it-tagħbija li titbandal b'idejk vojta.","Tagħbijiet li joxxillaw jistgħu jaffettwaw lin-nies u l-faċilitajiet; movimenti kalmi jnaqqsu r-riskju."],"k2-funkakku":["Il-kontroll tar-radju ta 'krejn għandu batterija dgħajfa. X'japplika?","Il-konnessjoni tista' tinkiser waqt l-irfigħ.","Neħħi tagħbija malajr qabel ma l-kontroll ifalli.","Jekk il-konnessjoni tintilef, ċċaqlaq it-tagħbija billi tiġbed fuq il-braga.","Żgura konnessjoni ta 'kontroll affidabbli qabel l-użu.","Kontroll u komunikazzjoni affidabbli huma prerekwiżiti għal movimenti kkontrollati tal-krejn."],"k2-mehrereanschlaeger":["Żewġ persuni jagħtu sinjali differenti lill-operatur tal-krejn fl-istess ħin. X'inhu sewwa?","Is-sinjali jikkontradixxu lil xulxin.","Tinterrompi l-moviment u ċċara r-responsabbiltà ċara.","Ippreferi s-sinjal tal-persuna aktar 'il bogħod.","Kompli l-moviment skond is-sentiment tiegħek stess.","Is-sewwieqa tal-krejnijiet jeħtieġu komunikazzjoni ċara u mhux ambigwa, speċjalment meta r-rotot tat-tagħbija jkunu konfużi."],"k2-endabschaltung":["Għaliex swiċċ tal-limitu m'għandux jintuża ħażin bħala limitazzjoni normali tal-puplesija?","It-tagħbija spiss titmexxa sad-distanza massima ta 'rfigħ.","Swiċċijiet tal-limitu ġeneralment jippermettu rfigħ aktar mgħaġġel mingħajr viżibilità.","Is-swiċċijiet tal-limitu huma apparati tas-sigurtà u ma jissostitwixxux it-tħaddim ikkontrollat.","Għandhom jintlaqtu kemm jista 'jkun ma' kull puplesija.","L-apparati tas-sigurtà jservu biex jipproteġu kontra l-perikli u m'għandhomx jintużaw żżejjed kif ippjanat."],"k2-wetterbeobachtung":["Ir-riħ jiżdied b'mod sinifikanti b'tagħbija ta 'żona kbira. X'inhu meħtieġ?","Żona ta 'komponent kbir taġixxi bħal qlugħ.","Dejjem għolli t-tagħbija ogħla sabiex ir-riħ ikollu inqas effett.","Ibdel il-bragi b'oħrajn irqaq.","Evalwa l-limiti tar-riħ u operattivi u aġġusta l-irfigħ jekk meħtieġ.","Ir-riħ jista 'jiġġenera forzi addizzjonali sinifikanti u movimenti tal-pendlu, speċjalment b'tagħbijiet ta' żona kbira."],"k2-ortswechsel":["X'inhu importanti meta ċċaqlaq krejn mobbli għal post ġdid?","Il-kundizzjonijiet ta' taħt il-ħamrija u ta' appoġġ jinbidlu.","Iċċekkja l-post tal-istand u l-appoġġ qabel ma terġa 'ttella' t-tagħbija.","Applika s-settings mill-post preċedenti mingħajr ma tiċċekkja.","Ħalli l-appoġġ aġġustat mill-ġdid waqt l-irfigħ.","Kull post ta 'installazzjoni jista' jkollu kundizzjonijiet differenti ta 'tagħbija ta' l-art u ta 'appoġġ."],"k2-betriebsbereich":["Krejn suppost jaħdem madwar triq. X'hemm bżonn li jiġi ċċarat?","Partijiet terzi jistgħu jidħlu fiż-żona ta’ periklu.","Żgura t-triq biss b'ħorn ta 'twissija.","Lockdowns meħtieġa, votazzjoni u miżuri ta’ protezzjoni quddiem iċ-ċentru.","Neħħi t-tagħbija fuq il-vetturi malajr kemm jista 'jkun mingħajr ma tassiguraha.","Ir-rotot tat-traffiku sikur jipprevjeni riskju mhux dovut għal partijiet terzi minn tagħbijiet u movimenti tal-krejn."],"k2-hochheben":["Wara l-lift tat-test, tagħbija mdendla b'mod ċar mgħawweġ. X'inhu sewwa?","Jidher li l-fokus kien iġġudikat ħażin.","Kompli rfigħ sabiex l-iżbilanċ jikkoreġi lilu nnifsu.","Have persuna waħda tiġbed it-tagħbija jegħleb.","Qiegħed it-tagħbija 'l isfel mingħajr periklu u erġa' ċċekkja t-twaħħil u ċ-ċentru tal-gravità.","Il-lift tat-test jintuża biex jiskopri twaħħil mhux korrett u pożizzjonijiet ta 'tagħbija mhux stabbli qabel it-trasport."],"k2-schwebelast":["Tista 'tħalli tagħbija mgħollija mdendla waħedha?","Il-bidla tispiċċa, iżda t-tagħbija għadha fuq il-ganċ.","Le, baxxi t-tagħbija b'mod sikur u waħħal il-krejn kif suppost.","Iva, jekk il-krejn ikun imsakkar kontra li jitbiegħed.","Iva, sakemm ikun hemm sinjal ta’ twissija fl-art.","Fil-prinċipju, tagħbijiet sospiżi m'għandhomx jitħallew waħedhom."],"k2-mitnahme":["Kollega jrid isuq fuq tagħbija tal-krejn. X'japplika?","It-tagħbija għandha tiġi ttrasportata lejn punt ogħla.","L-irkib huwa permess jekk il-kollega jilbes elmu.","In-nies ma jistgħux jiġu ttrasportati jew imwaħħla ma' tagħbijiet normali.","Rikba hija dejjem permessa sakemm il-kollega jkun magħruf mix-xufier tal-krejn.","Il-ġarr tan-nies flimkien ma 'tagħbijiet joħloq riskji sinifikanti ta' waqgħa u tgħaffiġ."],"k2-warnsignal":["Sistema ta 'twissija operattiva fuq il-krejn tfalli. X'inhu sewwa?","M'għadux possibbli li tingħata twissija qabel is-sewqan.","Injora s-sistema meta l-magna tkun qed taħdem.","Ibdel it-twissija b'mod permanenti billi ttektek il-housing.","Irrapporta falliment relatat mas-sikurezza u interrompi l-operazzjonijiet skont l-istruzzjonijiet.","L-apparati ta' twissija meħtieġa għandhom ikunu funzjonali sabiex in-nies ikunu protetti fil-ħin."],"k2-schneekante":["Krejn mobbli jeħtieġ li jkun appoġġjat fuq art iffriżata u irregolari. X'japplika?","Il-ħamrija tista' titlef il-kapaċità ta' ġarr tagħha hekk kif tinħall.","Evalwa l-kapaċità tat-tagħbija u s-sitwazzjoni ta 'appoġġ taħt kundizzjonijiet attwali.","L-art iffriżata dejjem għandha kwalunkwe kapaċità ta 'ġarr.","Poġġi biss appoġġi fuq ġebel żgħir.","It-temperatura, l-umdità u l-istruttura ta 'taħt il-ħamrija jinfluwenzaw il-kapaċità li ġġorr it-tagħbija tal-postijiet tal-krejn."],"k2-laufkatze":["Troli jimxi lejn ostaklu. Kif taġixxi?","Hemm oġġett fiż-żona tas-sewqan.","Bil-mod imbotta l-oġġett bogħod bit-tagħbija.","Waqqaf il-moviment fil-ħin u neħħi l-ostaklu b'mod sikur.","Issuq wara l-ostaklu b'veloċità akbar.","Il-movimenti tal-krejn għandhom ikunu ggwidati b'tali mod li ma jseħħu l-ebda ħabtiet ma' ostakli."],"k2-anschlagaufnahme":["Għandek taqbad tagħbija bl-użu ta' għajn mhux magħżula. X'inhu sewwa?","Il-malla tista' tkun maħsuba biss għall-immuntar ta' kopertura.","Kull għajn hija adattata għal tagħbija sħiħa tal-krejn.","Għabbi l-għajn biss b'żewġ persuni fl-istess ħin.","Ivverifika l-kapaċità tat-tagħbija u l-adegwatezza tal-punt tal-ankra qabel l-użu.","Mhux kull għajn eżistenti hija punt ta 'twaħħil stabbli għal tagħbijiet tal-krejn."],"l2-seilbruch":["Ħabel tal-wajer juri diversi wajers individwali miksura. X'inhu sewwa?","Il-punti ta 'tkissir huma fiż-żona tal-ħabel li ġġorr it-tagħbija.","Tkomplix tuża tagħmir tal-irfigħ u ċċekkjah professjonalment.","Liwja t-truf tal-wajer lura b'idejk vojta.","Kompli uża l-ħabel jekk it-tagħbija hija partikolarment ħafifa.","Il-waqfiet tal-wajer jistgħu jkunu kriterju ta' skartar; Ħbula bil-ħsara għandhom jiġu evalwati professjonalment."],"l2-schaekel":["X'inhu kruċjali meta tuża shackle?","Shackle jgħaqqad il-braga u t-tagħbija.","Ibdel il-bolt bi kwalunkwe dwiefer.","Iċċekkja għal kapaċità ta 'tagħbija xierqa, kundizzjoni mingħajr ħsara u boltijiet korretti.","Stima l-kapaċità tat-tagħbija bbażata fuq il-kulur.","Ix-shackles għandhom ikunu ta' daqs xieraq, użati kompletament u fid-direzzjoni maħsuba tat-tagħbija."],"l2-tragfaehigkeit":["X'għandek tikkunsidra meta tuża fergħat multipli?","Il-fergħat jimxu f'angolu mal-vertikali.","Sempliċement żid il-kapaċità tat-tagħbija ta 'kull linja kif mixtieq.","Iddendel it-tagħbija biss fuq l-eħfef linja.","Ikkunsidra l-kapaċità li ġġorr it-tagħbija tat-tip kollu ta 'ankra u angolu.","L-angolu ta 'inklinazzjoni u n-numru effettiv ta' linji jinfluwenzaw b'mod sinifikanti t-tagħbija permissibbli."],"l2-schweissnaht":["Jista 'punt ta' ankra improvizzati jiġi wweldjat ma 'tagħbija?","M'hemm l-ebda punti ta' ġbir magħżula xierqa għat-tagħbija.","Uża biss punti ta' ankra ddisinjati u approvati kif suppost.","Kwalunkwe ħjata ta 'weldjatura hija biżżejjed mingħajr ittestjar.","Daħħal ganċ minn fetħa fil-folja tal-metall.","Il-punti tal-ankri għandhom jiġu ppruvati li huma adattati għall-forzi involuti fl-irfigħ."],"l2-einseitig":["Tagħbija hija sinifikament itqal fuq naħa waħda. Kif tmur dwar dan?","Iċ-ċentru tal-gravità huwa barra miċ-ċentru ġeometriku.","Ħalli l-fergħat kollha bl-istess tul irrispettivament miċ-ċentru tal-gravità.","Iddetermina ċ-ċentru tal-gravità u aġġusta l-pożizzjoni kif xieraq.","L-ewwel għolli t-tagħbija għal għoli ta 'rfigħ sħiħ.","Jekk iċ-ċentru tal-gravità ma jkunx miċ-ċentru, it-tagħbijiet jistgħu jinqalbu b'mod mhux mistenni jew il-fergħat individwali jistgħu jiġu mgħobbija żżejjed."],"l2-kettenriss":["X'japplika għal braga tal-katina bi xquq viżibbli?","Hemm qasma f'waħda mill-ħoloq tal-katina.","Immarka l-qasma biż-żebgħa u erfaha mhux mibdula.","Kebbeb il-link bil-wajer u użaha mill-ġdid.","Neħħi l-katina immedjatament u informa lill-persuna responsabbli.","Xquq fil-ħoloq tal-katina li jġorru t-tagħbija huma ħsara rilevanti għas-sikurezza u jeħtieġu d-dekummissjonar."],"l2-lastfuehrung":["Kif iġorr tagħbija kbira meta jkun hemm riskju ta 'rotazzjoni?","It-tagħbija tista' titbandal 'il barra mal-ġenb waqt l-irfigħ.","Uża apparat xieraq ta' gwida u distanza sigura.","Żomm it-tagħbija direttament bejn idejk waqt is-sewqan.","Pass taħt it-tagħbija u allinjaha minn taħt.","Il-gwida tat-tagħbija m'għandhiex tikkawża li l-idejn jew il-korpi jidħlu fiż-żona ta' periklu."],"l2-schnueren":["X'inhu importanti meta twaħħal il-lazzijiet?","Il-braga hija ggwidata madwar komponent.","Assumi l-istess kapaċità ta 'tagħbija bħal kull tip ieħor ta' ankra.","Osserva l-adegwatezza tat-tip ta 'twaħħil u t-tagħbija permissibbli skont l-immarkar.","Iġbed l-irkaptu tal-braga flimkien sa kwalunkwe punt mingħajr ma tiċċekkja.","It-tip ta 'twaħħil tal-bizzilla jista' jibdel il-kapaċità tat-tagħbija permissibbli u għandu jintuża b'mod korrett."],"l2-winkelmesser":["Għaliex ma tistax tinjora angolu ċatt tal-linja?","Żewġ linji tal-braga jimxu kważi orizzontalment għat-tagħbija.","Angolu ċatt awtomatikament jagħmel il-fergħa aktar b'saħħitha.","It-tagħbija hija dejjem imqassma b'mod ugwali irrispettivament mill-angolu.","Forzi tal-linja għolja jistgħu jaqbżu l-kapaċità tat-tagħbija permissibbli.","Hekk kif l-angolu mal-vertikali jiżdied, l-istress fuq il-fergħat jiżdiedu."],"l2-heisse-last":["X'għandek bżonn tiċċekkja għal tagħbija sħuna?","Parti tal-azzar reċentement ġiet ittrattata bis-sħana.","Osserva l-limiti tat-temperatura tal-bragi u għażla xierqa.","Kull braga tat-tessuti tista 'tiflaħ kwalunkwe temperatura.","It-tikkettar ma jimpurtax meta jkun sħun.","It-temperatura tista 'taffettwa l-kapaċità tat-tagħbija permissibbli tal-bragi."],"l2-abstand":["Tista' tpoġġi subgħajk taħt it-tagħbija meta tpoġġiha?","It-tagħbija għandha tinżel fuq wiċċ bi preċiżjoni millimetrika.","Iva, jekk tilbes ingwanti tax-xogħol.","Le, żomm id-distanza tiegħek u uża l-għajnuniet xierqa.","Iva, jekk il-moviment tal-krejn huwa partikolarment bil-mod.","Partijiet tal-ġisem bejn it-tagħbija u l-bażi jistgħu jinqabdu."],"l2-verbindung":["Link ta 'konnessjoni tal-katina tal-braga mhix imsakkra. X'japplika?","Il-qafla hija nieqsa.","Uża l-bolt mingħajr is-serratura meta ħadd ma jkun qed jara.","Issiġilla l-element b'tejp li jwaħħal.","Tolqotx sakemm il-qafla tkun imwaħħla sew.","L-elementi li jgħaqqdu għandhom ikunu mwaħħla kompletament u skont id-disinn tagħhom."],"l2-lasthaken":["X'tiċċekkja meta mdendla fuq ganċ tal-krejn?","Diversi bragi għandhom jiġu ggwidati fil-ganċ.","Tiżgura t-twaħħil u l-adegwatezza siguri tal-ganċijiet u s-sospensjoni.","Poġġi bragi fuq il-ponta tal-ganċ.","Ibdel is-serratura tal-ganċ b'irbit tal-kejbil.","Il-forza għandha tiġi applikata kif maħsub fiż-żoni magħżula."],"l2-fasern":["Ċinga ta 'rfigħ turi ħruxija severa u ħsara fil-fibra. X'inhu sewwa?","Il-fibri ta 'appoġġ huma viżibbli bil-ħsara.","Għatti l-ħsara b'għoqda oħra.","Issepara ċ-ċinga tal-irfigħ u ċċekkjaha minn speċjalista.","Imbagħad neħħi t-tagħbija aktar malajr.","Fibri li jifilħu t-tagħbija bil-ħsara jistgħu jnaqqsu b'mod sinifikanti l-kapaċità ta 'ġarr ta' tagħbija ta 'ċinga ta' rfigħ."],"l2-anheben":["X'japplika immedjatament wara l-ewwel ċentimetru tal-irfigħ?","It-tagħbija qed titneħħa mill-bażi tagħha.","Iġbed it-tagħbija għall-għoli sħiħ tagħha mingħajr kontroll.","Iċċekkja taħt it-tagħbija jekk il-bragi humiex issikkati.","Iċċekkja l-pożizzjoni tal-waqfien, il-bilanċ u l-imġieba tal-moviment.","Lift tat-test ikkontrollat ​​jagħmel l-instabbiltà possibbli viżibbli qabel aktar trasport."],"l2-lastgewichte":["Il-piż tat-tagħbija mhux magħruf. X'inhu sewwa?","Il-komponent m'għandux immarkar tal-piż.","Iddetermina l-piż li jista' jitgħabba qabel ma tagħżel bragi.","Stima l-piż ibbażat fuq il-kulur tat-tagħbija.","Uża kwalunkwe braga ta 'tul doppju.","Mingħajr piż magħruf jew determinat b'mod affidabbli, l-adegwatezza tal-bragi ma tistax tiġi ċċekkjata b'ċertezza."],"l2-lose-teile":["Hemm għodda maħlula fuq it-tagħbija li trid titneħħa. X'qed tagħmel?","L-għodda jistgħu jaqgħu meta jerfgħu.","Żomm l-għodda b'id waħda meta ssuq.","Neħħi jew waħħal b'mod effettiv l-oġġetti maħlula qabel irfigħ.","Għolli t-tagħbija ftit aktar malajr sabiex xejn ma jiżloq.","Oġġetti sfużi jistgħu jaqgħu u jipperikolaw lin-nies fiż-żona."],"l2-wind":["Tagħbija kbira hija mwaħħla f'riħ qawwi. X'japplika?","Il-komponent joffri lir-riħ erja tal-wiċċ kbira biex jattakka.","Għolli t-tagħbija mingħajr ma tikkunsidra movimenti li jixxengel.","Nies addizzjonali għandhom iżommu t-tagħbija direttament.","Evalwa l-kundizzjonijiet tar-riħ u żżomm lura milli tneħħi jekk is-sitwazzjoni ma tkunx sigura.","Il-forzi tar-riħ jistgħu jaffettwaw il-gwida tat-tagħbija u l-istabbiltà waqt it-trasport."],"l2-unterlage":["Għaliex huma importanti dokumenti xierqa meta l-ftim?","Tagħbija tonda kienet tinqaleb fuq l-art.","Poġġi t-tagħbija sew 'l isfel u waħħalha kontra t-tidwir jekk meħtieġ.","Ħalli t-tagħbija wieqfa direttament fuq il-bragi.","Imbotta d-dokumenti taħt it-tagħbija biss wara li jkunu ġew stabbiliti.","Appoġġ addattat jipprevjeni l-qlib u movimenti mhux mixtieqa meta jinżel."],"l2-transportweg":["X'għandu jiġi kkoordinat qabel it-tagħbija tiġi ttrasportata?","It-tagħbija titmexxa fuq diversi żoni tax-xogħol.","Biss it-tul mistenni taċ-ċentru.","Mogħdija tat-tagħbija sikura, komunikazzjoni u ostakli meħtieġa.","Persuna waħda għandha turi t-triq taħt it-tagħbija.","It-trasport tat-tagħbijiet jeħtieġ rotot sikuri tat-traffiku u koordinazzjoni ċara."],"l2-schutzschlauch":["X'għandek tagħti attenzjoni meta tuża bragi b'pajp protettiv?","Faxxa tinsab kontra xifer mhux maħdum.","Kwalunkwe drapp irqiq tad-drapp jissostitwixxi protezzjoni xierqa tat-tarf.","Manka protettiva tneħħi kwalunkwe limitu ta' tagħbija permissibbli.","Agħżel tagħmir protettiv skont ir-rekwiżiti tal-adegwatezza u tal-applikazzjoni.","It-tagħmir protettiv għandu jaqbel mal-materjal, it-tarf u t-tagħbija maħsuba."],"l2-reinigung":["Ċinga tal-irfigħ kienet ikkontaminata b'kimika mhux magħrufa. X'inhu sewwa?","It-tejp ma jistax jibqa' jiġi vvalutat b'mod ċar.","Waqqaf l-użu u ċċara l-kompatibilità jew il-kundizzjoni professjonalment.","Naddaf bi kwalunkwe solvent u kompli rfigħ immedjatament.","Injora l-kimika waqt li t-tejp ikun niexef.","Il-kimiċi jistgħu jaffettwaw is-saħħa tal-bragi tat-tessuti."],"l2-aufhaengung":["X'tiċċekkja għal linji multipli fuq il-link tas-sospensjoni?","Żewġ linji jitqiegħdu flimkien f'sospensjoni.","Fergħa tista 'tiċċaqlaq fil-ponta tal-ganċ kif rieda.","L-elementi kollha ta' konnessjoni għandhom ikunu adattati u rranġati kif maħsub.","Ċirku bi qasma jista 'jintuża għal tagħbijiet żgħar.","L-elementi ta 'waqfien u ta' konnessjoni għandhom ikunu li jifilħu t-tagħbija u rranġati b'mod korrett."],"l2-einweiserrolle":["X'japplika jekk l-attakkant u l-operatur tal-krejn ma jkollhom l-ebda linja tal-vista?","Trasportatur jimblokka l-vista tal-punt tal-waqgħa.","Ikkoordina billi ċċempel diversi nies mingħajr responsabbiltà.","Mexxi t-tagħbija bbażata fuq l-istorbju mingħajr istruzzjoni.","Organizza komunikazzjoni ċara u sigura u waqqafha jekk ma tkunx ċara.","In-nuqqas ta' viżibilità għandu jiġi kkumpensat b'koordinazzjoni effettiva u komunikazzjoni sigura."],"l2-ausserbetrieb":["Ġiet solvuta braga bil-ħsara. X'iktar huwa importanti?","Jibqa' aċċessibbli liberament flimkien ma' riżorsi lesti għall-użu.","Żgura kontra aktar użu aċċidentali u informa lill-persuna responsabbli.","Irritorna l-prodott mhux immarkat fl-inventarju.","Użaha mill-ġdid biss meta ġġorr tagħbija partikolarment ħafifa.","Bragi mormija għandhom ikunu protetti b'mod affidabbli qabel aktar użu."],"b2-schwenkradius":["Għaliex ir-raġġ tat-tbandil ta 'wara ta' excavator huwa kritiku?","Id-denb jiċċaqlaq fuq żona ta 'xogħol limitata.","Partijiet terzi jistgħu jinqabdu mis-sovrastruttura li tbandal.","Ir-raġġ tat-tbandil m'għandu l-ebda influwenza fuq in-nies ħdejn il-magna.","In-naħa ta 'wara dejjem timxi biss fid-direzzjoni tal-ivvjaġġar.","Meta ddur, tinħoloq żona ta 'periklu wkoll wara l-magna."],"b2-verkehrseinweiser":["Kif jiġi żgurat moviment tas-sewqan meta l-viżibilità tkun mgħottija?","Skavatur irid jimmanuvra wara ostaklu.","Issuq mingħajr ma tara s-sinjali tas-sinjalatur.","Jekk meħtieġ, organizza struzzjoni xierqa b'komunikazzjoni ċara.","Aċċerta biss ir-rivers billi tgħaqqad il-ħonna darba.","Rotot konfużi jeħtieġu miżuri effettivi biex jipprevjenu ħabtiet u qbid."],"b2-standplatz":["X'japplika għal stand ta' skavatur fuq inklinazzjoni?","L-art hija mżerżqa u tista' tkun tiżloq.","Il-magna tista 'testendi sa fejn tixtieq fi kwalunkwe inklinazzjoni.","Dejjem waqqaf l-iskavatur fuq saff maħlul ta 'art.","Iċċekkja l-istabbiltà u l-limiti operattivi tal-magna qabel l-użu.","L-inklinazzjoni u s-sottoħamrija għandhom influwenza sinifikanti fuq l-istabbiltà."],"b2-oberleitung":["Għaliex trid tiġi ppjanata d-distanza tal-boom mill-linji tal-enerġija?","Il-boom jista 'jiġi qrib il-kejbil meta jdur.","Flashover elettriku huwa wkoll possibbli mingħajr kuntatt dirett.","Il-barmil biss jista 'jmexxi l-elettriku, mhux il-boom.","Bil-ħamrija niexfa, kull distanza hija awtomatikament sigura.","Il-limiti tal-użu u d-distanzi protettivi għandhom jiġu ċċarati qabel ma jersqu lejn is-sistemi elettriċi."],"b2-fremdperson":["Jidħol fil-post tal-kostruzzjoni fiż-żona tal-panning. X'inhu sewwa?","Il-persuna f'daqqa waħda toqgħod ħdejn il-barmil tal-iskavatur.","Erfa 'l-pala 'l fuq u tbandalha fuq il-persuna.","Waqqaf il-moviment immedjatament u neħħi ż-żona.","Eżatt kompli tara l-persuna mit-tieqa tal-ġenb.","In-nies fiż-żona ta' periklu m'għandhomx ikunu pperikolati minn movimenti tax-xogħol."],"b2-parkstellung":["Kif titwaħħal magna tal-art wara li jintemm ix-xogħol?","L-iskavatur jibqa’ waħdu fuq is-sit tal-kostruzzjoni.","Ħalli l-kuċċarina fl-għoli tar-ras.","Ħalli l-magna taħdem waħedha.","Poġġi t-tagħmir tax-xogħol, waħħal il-magna u tevita użu mhux awtorizzat.","L-ipparkjar xieraq inaqqas il-moviment aċċidentali u l-aċċess mhux awtorizzat."],"b2-eigenlast":["Għaliex il-limiti tat-tagħmir huma kruċjali meta l-irfigħ bi skavatur?","Tagħbija tqila għandha tinġabar fuq il-boom.","Inkella, l-istabbiltà u l-kapaċità tat-tagħbija permissibbli jistgħu jinqabżu.","Kwalunkwe magna tista 'ttella' kwalunkwe tagħbija sakemm il-barmil joqgħod.","It-tul tal-ħabel tal-braga biss jiddetermina r-riskju.","L-informazzjoni dwar il-kapaċità tal-irfigħ u t-tagħbija tiddependi fuq it-tagħmir u s-sitwazzjoni tal-applikazzjoni."],"b2-untergrundhohlraum":["L-art 'il fuq minn kantina antik tista' tkun vojta. X'qed tagħmel?","Għandek issuq l-iskavatur fiż-żona.","Aqsam il-post b'momentum massimu.","Iċċara l-kapaċità tat-tagħbija u l-kavitajiet possibbli qabel issuq fuq.","Sempliċement poġġi tagħbija tqila fuq il-wiċċ.","Il-kavitajiet jistgħu jiġġarfu taħt il-piż tal-magna u jikkawżaw li l-magna tiġġarraf."],"b2-feuchtigkeit":["Wara xita qawwija l-moll isir artab. X'inhu sewwa?","Skavatur jaħdem ħdejn it-tarf tal-moll.","Mexxi l-magna eqreb lejn it-tarf biex iżżid il-firxa.","Injora l-bidliet sa tmiem ix-xift.","Ivvaluta mill-ġdid il-kundizzjonijiet tal-ħamrija u l-istabbiltà.","Il-penetrazzjoni tal-umdità tista 'tbiddel il-kapaċità li tiflaħ it-tagħbija u l-istabbiltà tal-moll."],"b2-bodenprobe":["Għaliex il-pjanijiet tal-pipeline għandhom jiġu ċċekkjati qabel it-tħaffir?","Kejbils jistgħu jimxu taħt l-iskavar ippjanat.","Sabiex il-linji jkunu jistgħu jiġu identifikati u jkunu jistgħu jiġu ppjanati miżuri ta' sigurtà xierqa.","Sabiex it-tħaffir ikun jista 'jsir aktar malajr, indipendentement minn sistemi ta' partijiet terzi.","Għax il-magni m'għandhom qatt jintużaw ħdejn il-kejbils.","Il-linji tal-provvista taħt l-art jeħtieġu kjarifika tal-post affidabbli qabel ix-xogħol ta 'tħaffir."],"b2-maschinenzugang":["X'japplika meta tidħol u toħroġ mill-magna tal-art?","Il-magna tinsab fuq art irregolari.","Żerżaq 'l isfel mil-linja idrawlika 'l barra mill-kabina.","Uża passi magħżula u aċċerta ruħek li tkun sigura.","Aqbeż fuq id-driegħ li jdur waqt li l-magna tkun qed taħdem.","Tlugħ sigur u punti ta 'waqfien adattati jnaqqsu r-riskju ta' waqgħa u tgħaffiġ."],"b2-kupplung":["Kif tiċċekkja backhoe ġdid wara l-installazzjoni?","Il-barmil huwa konness permezz tal-quick coupler.","Iġġudika l-kuċċarina biss viżwalment minn distanza akbar.","Pass direttament taħt il-kuċċarina mgħollija.","Żgura l-illokkjar korrett u l-passi ta 'kontroll preskritti.","L-annessi li huma msakkra ħażin jistgħu jinħallu u jipperikolaw lin-nies."],"b2-hydraulikwartung":["Għaliex il-linji idrawliċi mhumiex permessi li jinfetħu taħt pressjoni?","Manka trid tiġi sostitwita.","Il-fluwidu li joħroġ jista 'jikkawża korrimenti serji minħabba pressjoni għolja.","Il-pressjoni dejjem tipprevjeni ż-żejt milli jaħrab.","Linja miftuħa tista 'tiġi kkontrollata b'mod sikur b'idejk.","Fluwidu bi pressjoni għolja jista 'jippenetra t-tessut u jeħtieġ serħan tal-pressjoni sikur."],"b2-fahrweg":["Int trid issuq fuq pont ta 'kostruzzjoni temporanju. X'qed tiċċekkja?","Il-pont huwa ddisinjat biss għal ċerti tagħbijiet.","Jekk il-kulur tal-pont jaqbilx mal-magna.","Kapaċità tat-tagħbija u adattabilità għall-piż u d-dimensjonijiet tal-magna.","Biss jekk karozza ħafifa tkun diġà saq fuq il-pont.","L-istrutturi temporanji jistgħu jintużaw biss fil-kapaċità ppruvata tagħhom ta' ġarr ta' tagħbija."],"b2-baggertransport":["X'inhu importanti meta tittrasporta excavator fuq loader baxx?","Il-magna tittieħed fis-sit tal-kostruzzjoni li jmiss.","Ħalli t-tagħmir tax-xogħol joħroġ laxk fuq it-tarf.","Żomm il-bieba tal-kabina miftuħa waqt is-sewqan.","Sikura l-magna skond l-ispeċifikazzjonijiet tat-trasport u iċċekkja t-tagħmir tat-tagħbija.","Serraturi tat-trasport u faċilitajiet ta 'tagħbija xierqa jipprevjenu ż-żliq u l-waqgħa."],"b2-schaufelfuellung":["Għaliex loader tar-roti mhux permess li jsuq malajr bil-barmil mgħolli għoli?","It-tagħbija hija tqila u l-art hija irregolari.","Ċentru ta' gravità għoli jista' jżid ir-riskju ta' twaddib u problemi ta' viżibilità.","Il-barmil jistabbilizza awtomatikament b'veloċitajiet għoljin.","L-għoli tal-pala huwa irrilevanti għall-istabbiltà.","Ċentru tal-gravità mgħolli tipikament jaggrava l-istabbiltà waqt is-sewqan u l-irkejjen."],"b2-fussgaenger":["Kif taġixxi meta timmanuvra ħdejn il-persuni mexjin?","L-aċċess għas-sit tal-kostruzzjoni huwa wkoll passaġġ.","Uża l-pala biex tidderieġi l-pedestrians lejn il-ġenb.","Wettaq il-moviment tas-sewqan biss meta ż-żona tkun ċara u maniġġabbli b'mod sikur.","Ħonk biss darba u ssuq bil-mod mingħajr viżibilità.","It-traffiku tal-vetturi u tal-passiġġieri għandu jkun separat b'mod effettiv jew ikkoordinat b'mod sikur."],"b2-ueberlastwarnung":["Waqt l-irfigħ, il-magna tirrapporta tagħbija żejda. X'qed tagħmel?","Tagħbija mgħollija tilħaq il-limiti permissibbli.","Itfi t-twissija u kompli għolliha mhux mibdula.","Issikka t-tagħbija f'daqqa waqt li l-magna tkun qed taħdem.","Waqqaf movimenti perikolużi u kkoreġi b'mod sigur is-sitwazzjoni tat-tagħbija.","Twissijiet ta 'tagħbija żejda jindikaw ksur possibbli tal-limitu u riskji ta' stabbiltà."],"b2-wasserleitung":["Waqt it-tħaffir, jinkixef pajp mhux magħruf. X'japplika?","Il-linja mhix murija fil-pjanijiet tal-kostruzzjoni.","Waqqaf ix-xogħol fiż-żona affettwata u agħmel il-linja identifikata professjonalment.","Ipprova ċċaqlaq il-linja bil-pala tal-iskavatur.","Kompli tħaffer direttament taħt il-linja mingħajr ma tiċċekkja.","Linji mhux magħrufa jistgħu jikkawżaw perikli elettriċi, tal-gass jew tal-ilma."],"b2-hangefahrt":["Kif issuq excavator fuq inklinazzjoni wieqfa?","Ir-rotta ppjanata twassal tul inklinazzjoni.","Issuq tul l-inklinazzjoni irrispettivament mil-limiti tal-manifattur.","Osserva l-inklinazzjoni permissibbli u l-istil tas-sewqan preskritt tal-magna.","Itbandal il-boom 'il bogħod biex tibbilanċja l-vettura.","L-inklinazzjoni permissibbli tiddependi fuq il-magna, il-wiċċ u l-informazzjoni tal-manifattur."],"b2-schlechtebeleuchtung":["Meta taħdem f'fossa mudlama, il-viżibilità hija inadegwata. X'inhu sewwa?","Bilkemm tista’ tara n-nies u l-ostakli.","Żid il-veloċità tat-tħaffir biex tlesti l-operazzjoni malajr.","Tużax id-dwal waqt li l-magna tkun qed taħdem.","Waqqaf ix-xogħol sakemm iż-żoni ta' periklu jkunu viżibbli biżżejjed.","Viżibilità sigura taż-żoni tas-sewqan u tax-xogħol hija meħtieġa għal movimenti kkontrollati tal-magni."],"b2-kettenverschleiss":["Matul il-kontroll ta 'kuljum, hija nnotata binarju tal-caterpillar bil-ħsara. X'qed tagħmel?","Konnessjoni tal-katina turi ħsara ċara.","Tkomplix tuża l-magna mingħajr kontroll u rrapporta kwalunkwe ħsara.","Kompli sewqan b'veloċità għolja sabiex il-katina tiddritta.","Kompli taħdem biss fuq art ratba mingħajr ma tiċċekkja.","Ħsara lis-sewqan tista 'tfixkel il-kontrollabbiltà u l-istabbiltà."],"b2-ladearbeiten":["Int tagħbija trakk bl-iskavatur. X'inhu importanti?","Is-sewwieq tat-trakk jibqa’ qrib iż-żona tat-tagħbija.","Itbandal il-barmil fuq il-kabina tas-sewwieq mhux protett.","Tipprevjeni lin-nies milli joqogħdu fiż-żona ta 'periklu u tikkoordina l-proċessi.","Ibda t-tagħbija mingħajr ma tikkomunika max-xufier.","Waqt it-tagħbija hemm riskju li jaqa 'materjal u movimenti li jixxengel."],"b2-arbeitsunterbrechung":["Tinterrompi x-xogħol ta' tħaffir għal laqgħa. X'japplika?","Il-magna għandha toqgħod għal diversi minuti mingħajr ma titħaddem.","Ħalli l-pala mgħollija bħala markatur.","Ħalli l-magna waħedha bil-traction drive ingaġġat.","Poġġi l-istrument b'mod sigur u waħħal il-magna kontra użu mhux intenzjonat.","Anke interruzzjonijiet qosra jeħtieġu kundizzjoni tal-magna sigura."],"b2-rollmaterial":["Materjal maħlul jista' jaqa' meta jiġi ttrasportat bit-wheel loader. X'inhu sewwa?","Il-loader isuq qrib l-impjegati.","Aqbad it-tagħbija b'mod sikur u agħżel stil ta 'sewqan sikur b'pożizzjoni xierqa ta' pala.","Għolli l-pala kemm jista 'jkun sabiex iż-żona tal-madwar ikollha veduta ċara.","Aqbad it-tagħbija mingħajr ma tillimita l-mili tal-barmil.","Tagħbijiet maħlula, pożizzjonijiet għolja tal-barmil u viżibilità fqira jistgħu jipperikolaw lin-nies u t-traffiku."]};
